const JOHN_SECTIONS = {};

JOHN_SECTIONS["1"] = [{"title":"Slovo se stalo tělem","range":"Jan 1,1–18","thoughts":[],"verses":[[1,"Na počátku bylo Slovo. Slovo bylo u Boha a to Slovo bylo Bůh."],[2,"Bylo na počátku u Boha."],[3,"Všechno vzniklo skrze ně a bez něho nevzniklo nic z toho, co existuje."],[4,"V něm byl život a tento život byl světlem lidí."],[5,"Světlo svítí v temnotě a temnota je nepohltila."],[6,"Od Boha byl poslán člověk jménem Jan."],[7,"Přišel jako svědek, aby vydal svědectví o tom světle a aby skrze něj všichni uvěřili."],[8,"On sám nebyl tím světlem; přišel, aby o světle vydal svědectví."],[9,"To pravé světlo, které osvěcuje každého člověka, přicházelo na svět."],[10,"Bylo na světě, svět skrze ně vznikl, ale svět ho nepoznal."],[11,"Přišel do svého vlastního, ale jeho vlastní ho nepřijali."],[12,"Těm, kteří ho přijali a věří v jeho jméno, však dal právo stát se Božími dětmi."],[13,"Ti se nenarodili z krve ani z vůle těla či člověka, ale z Boha."],[14,"A Slovo se stalo tělem a přebývalo mezi námi. Viděli jsme jeho slávu, slávu jednorozeného od Otce, plného milosti a pravdy."],[15,"Jan o něm vydával svědectví a volal: „To je ten, o němž jsem řekl: Ten, který přichází po mně, je přede mnou, protože byl dříve než já.“"],[16,"Z jeho plnosti jsme všichni přijali milost za milostí."],[17,"Zákon byl dán skrze Mojžíše, ale milost a pravda přišly skrze Ježíše Krista."],[18,"Boha nikdy nikdo neviděl. Jednorozený Syn, který je v Otcově náruči, nám ho dal poznat."]]},{"title":"Svědectví Jana Křtitele","range":"Jan 1,19–34","thoughts":[],"verses":[[19,"Toto je Janovo svědectví, když k němu Židé z Jeruzaléma poslali kněze a levity, aby se ho zeptali: „Kdo jsi?“"],[20,"Jan nic nezapíral, ale otevřeně vyznal: „Já nejsem Mesiáš.“"],[21,"Zeptali se ho: „Kdo tedy? Jsi Eliáš?“ Odpověděl: „Nejsem.“ „Jsi ten Prorok?“ Odpověděl: „Ne.“"],[22,"Řekli mu tedy: „Kdo jsi? Musíme dát odpověď těm, kteří nás poslali. Co říkáš sám o sobě?“"],[23,"Jan odpověděl: „Jsem hlas volajícího na poušti: ‚Narovnejte cestu Pánu,‘ jak řekl prorok Izajáš.“"],[24,"Ti, kdo byli posláni, patřili k farizeům."],[25,"Zeptali se ho: „Proč tedy křtíš, když nejsi Mesiáš ani Eliáš ani ten Prorok?“"],[26,"Jan jim odpověděl: „Já křtím vodou, ale mezi vámi stojí někdo, koho neznáte."],[27,"To je ten, který přichází po mně a je přede mnou. Nejsem hoden ani rozvázat řemínek jeho sandálu.“"],[28,"To se stalo v Betabaře za Jordánem, kde Jan křtil."],[29,"Druhého dne Jan uviděl Ježíše, jak k němu přichází, a řekl: „Hle, Beránek Boží, který snímá hřích světa!"],[30,"To je ten, o němž jsem řekl: ‚Za mnou přichází muž, který je přede mnou, protože byl dříve než já.‘"],[31,"Ani já jsem ho neznal. Přišel jsem však křtít vodou proto, aby byl zjeven Izraeli.“"],[32,"Jan také vydal svědectví: „Viděl jsem Ducha sestupovat z nebe jako holubici a zůstávat na něm."],[33,"Ani já jsem ho neznal, ale ten, který mě poslal křtít vodou, mi řekl: ‚Na koho uvidíš sestupovat Ducha a zůstávat na něm, to je ten, který křtí Duchem svatým.‘"],[34,"Já jsem to viděl a dosvědčuji, že on je Boží Syn.“"]]},{"title":"První učedníci","range":"Jan 1,35–42","thoughts":[],"verses":[[35,"Druhého dne tam Jan znovu stál se dvěma ze svých učedníků."],[36,"Když uviděl Ježíše, jak jde kolem, řekl: „Hle, Beránek Boží!“"],[37,"Ti dva učedníci slyšeli, co řekl, a šli za Ježíšem."],[38,"Ježíš se obrátil, uviděl je, jak jdou za ním, a zeptal se: „Co hledáte?“ Odpověděli: „Rabbi,“ což znamená Mistře, „kde bydlíš?“"],[39,"Řekl jim: „Pojďte a uvidíte.“ Šli tedy, viděli, kde bydlí, a zůstali u něj ten den. Bylo kolem desáté hodiny."],[40,"Jedním z těch dvou, kteří slyšeli Jana a šli za Ježíšem, byl Ondřej, bratr Šimona Petra."],[41,"Ten nejprve našel svého bratra Šimona a řekl mu: „Našli jsme Mesiáše,“ což znamená Kristus."],[42,"A přivedl ho k Ježíšovi. Ježíš se na něj podíval a řekl: „Ty jsi Šimon, syn Jonášův. Budeš se jmenovat Kéfas,“ což znamená Petr."]]},{"title":"Filip a Natanael","range":"Jan 1,43–51","thoughts":[],"verses":[[43,"Následujícího dne se Ježíš rozhodl odejít do Galileje. Našel Filipa a řekl mu: „Následuj mě.“"],[44,"Filip byl z Betsaidy, města Ondřejova a Petrova."],[45,"Filip našel Natanaela a řekl mu: „Našli jsme toho, o němž psal Mojžíš v Zákoně i Proroci: Ježíše, syna Josefova z Nazareta.“"],[46,"Natanael mu řekl: „Může z Nazareta vzejít něco dobrého?“ Filip odpověděl: „Pojď a podívej se.“"],[47,"Když Ježíš uviděl Natanaela, jak k němu přichází, řekl o něm: „Hle, opravdový Izraelita, v němž není lest.“"],[48,"Natanael se zeptal: „Odkud mě znáš?“ Ježíš mu odpověděl: „Ještě než tě Filip zavolal, viděl jsem tě pod fíkovníkem.“"],[49,"Natanael mu odpověděl: „Mistře, ty jsi Boží Syn, ty jsi král Izraele!“"],[50,"Ježíš mu řekl: „Věříš proto, že jsem ti řekl, že jsem tě viděl pod fíkovníkem? Uvidíš ještě větší věci.“"],[51,"A dodal: „Amen, amen, říkám vám: Uvidíte otevřené nebe a Boží anděly vystupovat a sestupovat na Syna člověka.“"]]}];

JOHN_SECTIONS["2"] = [{"title":"Svatba v Káně","range":"Jan 2,1–12","thoughts":[],"verses":[[1,"Třetího dne se konala svatba v galilejské Káně a byla tam Ježíšova matka."],[2,"Na svatbu byl pozván také Ježíš se svými učedníky."],[3,"Když došlo víno, řekla Ježíšova matka: „Nemají víno.“"],[4,"Ježíš jí odpověděl: „Ženo, co to ode mě žádáš? Moje hodina ještě nepřišla.“"],[5,"Jeho matka řekla služebníkům: „Udělejte všechno, co vám řekne.“"],[6,"Stálo tam šest kamenných nádob určených k židovskému očišťování; každá pojala dvě až tři míry."],[7,"Ježíš služebníkům řekl: „Naplňte ty nádoby vodou.“ Naplnili je až po okraj."],[8,"Potom jim řekl: „Teď naberte a doneste správci hostiny.“ A oni mu donesli."],[9,"Správce hostiny ochutnal vodu, která se proměnila ve víno. Nevěděl, odkud víno je, ale služebníci, kteří vodu nabírali, to věděli. Zavolal ženicha"],[10,"a řekl mu: „Každý podává nejprve dobré víno a teprve když se hosté napijí, přinese horší. Ty jsi však dobré víno uchoval až doteď.“"],[11,"Toto první znamení udělal Ježíš v galilejské Káně. Zjevil svou slávu a jeho učedníci v něj uvěřili."],[12,"Potom sestoupil do Kafarnaum spolu se svou matkou, bratry a učedníky. Zůstali tam několik dní."]]},{"title":"Vyčištění chrámu","range":"Jan 2,13–25","thoughts":[],"verses":[[13,"Blížily se židovské Velikonoce a Ježíš vystoupil do Jeruzaléma."],[14,"V chrámě našel prodavače volů, ovcí a holubic a také penězoměnce sedící u svých stolů."],[15,"Udělal si z provázků bič a všechny vyhnal z chrámu, ovce i dobytek. Penězoměncům rozsypal mince a převrátil jejich stoly."],[16,"Prodavačům holubic řekl: „Odneste to odsud! Nedělejte z domu mého Otce tržiště.“"],[17,"Jeho učedníci si vzpomněli, že je napsáno: „Horlivost pro tvůj dům mě stravuje.“"],[18,"Židé se ho zeptali: „Jakým znamením nám prokážeš, že smíš takto jednat?“"],[19,"Ježíš jim odpověděl: „Zbořte tento chrám a za tři dny ho znovu postavím.“"],[20,"Židé řekli: „Tento chrám se stavěl čtyřicet šest let, a ty ho chceš postavit za tři dny?“"],[21,"On však mluvil o chrámu svého těla."],[22,"Když potom vstal z mrtvých, jeho učedníci si vzpomněli, že to říkal. Uvěřili Písmu i slovu, které Ježíš řekl."],[23,"Když byl o velikonočních svátcích v Jeruzalémě, mnozí uvěřili v jeho jméno, protože viděli znamení, která dělal."],[24,"Ježíš se jim však nesvěřoval, protože všechny znal."],[25,"Nepotřeboval, aby mu někdo vydával svědectví o člověku. Sám totiž věděl, co je v člověku."]]}];

JOHN_SECTIONS["3"] = [{"title":"Ježíš a Nikodém","range":"Jan 3,1–21","thoughts":[],"verses":[[1,"Mezi farizeji byl muž jménem Nikodém, jeden z předních mužů mezi Židy."],[2,"Ten přišel k Ježíšovi v noci a řekl mu: „Mistře, víme, že jsi učitel, který přišel od Boha. Nikdo totiž nemůže dělat znamení, která děláš ty, není-li s ním Bůh.“"],[3,"Ježíš mu odpověděl: „Amen, amen, říkám ti: Kdo se nenarodí znovu, nemůže spatřit Boží království.“"],[4,"Nikodém se zeptal: „Jak se může člověk narodit, když je starý? Může snad podruhé vstoupit do života své matky a narodit se?“"],[5,"Ježíš odpověděl: „Amen, amen, říkám ti: Kdo se nenarodí z vody a z Ducha, nemůže vejít do Božího království."],[6,"Co se narodilo z těla, je tělo, a co se narodilo z Ducha, je duch."],[7,"Nediv se, že jsem ti řekl: Musíte se narodit znovu."],[8,"Vítr vane, kam chce. Slyšíš jeho hlas, ale nevíš, odkud přichází ani kam jde. Tak je to s každým, kdo se narodil z Ducha.“"],[9,"Nikodém se ho zeptal: „Jak se to může stát?“"],[10,"Ježíš mu odpověděl: „Ty jsi učitel Izraele, a nevíš to?"],[11,"Amen, amen, říkám ti: Mluvíme o tom, co víme, a svědčíme o tom, co jsme viděli, ale naše svědectví nepřijímáte."],[12,"Když jsem vám mluvil o pozemských věcech a nevěříte, jak uvěříte, budu-li vám mluvit o nebeských?"],[13,"Nikdo nevystoupil do nebe kromě toho, který z nebe sestoupil: Syna člověka, který je v nebi."],[14,"A jako Mojžíš vyzdvihl hada na poušti, tak musí být vyzdvižen Syn člověka,"],[15,"aby každý, kdo v něj věří, nezahynul, ale měl věčný život."],[16,"Bůh totiž tak miloval svět, že dal svého jednorozeného Syna, aby žádný, kdo v něj věří, nezahynul, ale měl věčný život."],[17,"Bůh neposlal svého Syna na svět proto, aby svět odsoudil, ale aby byl svět skrze něj zachráněn."],[18,"Kdo v něj věří, není odsouzen. Kdo však nevěří, už je odsouzen, protože neuvěřil ve jméno jednorozeného Božího Syna."],[19,"A soud spočívá v tom, že světlo přišlo na svět, ale lidé si zamilovali tmu víc než světlo, protože jejich skutky byly zlé."],[20,"Každý, kdo jedná zle, nenávidí světlo a nejde ke světlu, aby jeho skutky nebyly odhaleny."],[21,"Kdo však žije podle pravdy, přichází ke světlu, aby se ukázalo, že jeho skutky byly vykonány v Bohu.“"]]},{"title":"Janovo poslední svědectví","range":"Jan 3,22–36","thoughts":[],"verses":[[22,"Potom přišel Ježíš se svými učedníky do Judska. Nějaký čas tam s nimi pobýval a křtil."],[23,"Také Jan křtil v Enonu blízko Salimu, protože tam bylo mnoho vody. Lidé k němu přicházeli a dávali se křtít."],[24,"Jan tehdy ještě nebyl uvězněn."],[25,"Mezi Janovými učedníky a jedním Židem vznikl spor o očišťování."],[26,"Přišli tedy k Janovi a řekli mu: „Mistře, ten, který byl s tebou za Jordánem a o němž jsi vydal svědectví, teď sám křtí a všichni jdou k němu.“"],[27,"Jan odpověděl: „Člověk si nemůže vzít nic, pokud mu to nebylo dáno z nebe."],[28,"Vy sami jste svědky toho, že jsem řekl: ‚Já nejsem Mesiáš, ale byl jsem poslán před ním.‘"],[29,"Ženich je ten, kdo má nevěstu. Ženichův přítel stojí, naslouchá mu a raduje se z jeho hlasu. Právě proto je má radost nyní úplná."],[30,"On musí růst a já se musím zmenšovat."],[31,"Kdo přichází shůry, je nade všemi. Kdo je ze země, patří zemi a mluví o pozemských věcech. Ten, kdo přichází z nebe, je nade všemi."],[32,"Svědčí o tom, co viděl a slyšel, ale jeho svědectví téměř nikdo nepřijímá."],[33,"Kdo jeho svědectví přijímá, potvrzuje tím, že Bůh mluví pravdu."],[34,"Ten, koho Bůh poslal, mluví Boží slova, protože Bůh mu dává Ducha bez míry."],[35,"Otec miluje Syna a všechno vložil do jeho rukou."],[36,"Kdo věří v Syna, má věčný život. Kdo však Synu nevěří, život neuvidí; zůstává na něm Boží hněv."]]}];

JOHN_SECTIONS["4"] = [{"title":"Ježíš a samařská žena","range":"Jan 4,1–42","thoughts":[],"verses":[[1,"Když se Pán dozvěděl, že farizeové slyšeli, že Ježíš získává a křtí více učedníků než Jan,"],[2,"ačkoli Ježíš sám nekřtil, ale jeho učedníci,"],[3,"opustil Judsko a znovu odešel do Galileje."],[4,"Musel přitom projít Samařskem."],[5,"Přišel tedy k samařskému městu zvanému Sychar, nedaleko pozemku, který Jákob dal svému synu Josefovi."],[6,"Byla tam Jákobova studna. Ježíš, unavený cestou, si u ní sedl. Bylo kolem poledne."],[7,"Přišla tam samařská žena nabrat vodu. Ježíš jí řekl: „Dej mi napít.“"],[8,"Jeho učedníci totiž odešli do města nakoupit jídlo."],[9,"Samařská žena mu řekla: „Jak to, že ty, Žid, žádáš o napití mě, Samařanku?“ Židé se totiž se Samařany nestýkali."],[10,"Ježíš jí odpověděl: „Kdybys znala Boží dar a věděla, kdo je ten, který ti říká: ‚Dej mi napít,‘ požádala bys ho ty a on by ti dal živou vodu.“"],[11,"Žena mu řekla: „Pane, nemáš ani čím nabrat a studna je hluboká. Odkud tedy vezmeš tu živou vodu?"],[12,"Jsi snad větší než náš otec Jákob, který nám tuto studnu dal a sám z ní pil, stejně jako jeho synové a dobytek?“"],[13,"Ježíš jí odpověděl: „Každý, kdo pije tuto vodu, bude znovu žíznit."],[14,"Kdo se však napije vody, kterou mu dám já, nebude žíznit navěky. Voda, kterou mu dám, se v něm stane pramenem vody tryskající k věčnému životu.“"],[15,"Žena mu řekla: „Pane, dej mi tu vodu, abych už neměla žízeň a nemusela sem chodit nabírat.“"],[16,"Ježíš jí řekl: „Jdi, zavolej svého muže a přijď sem.“"],[17,"Žena odpověděla: „Nemám muže.“ Ježíš jí řekl: „Správně jsi řekla: ‚Nemám muže.‘"],[18,"Měla jsi totiž pět mužů a ten, kterého máš teď, není tvůj muž. To jsi řekla pravdu.“"],[19,"Žena mu řekla: „Pane, vidím, že jsi prorok."],[20,"Naši otcové se klaněli Bohu na této hoře, ale vy říkáte, že místem, kde se má člověk klanět Bohu, je Jeruzalém.“"],[21,"Ježíš jí řekl: „Ženo, věř mi, přichází hodina, kdy se nebudete Otci klanět ani na této hoře, ani v Jeruzalémě."],[22,"Vy se klaníte tomu, co neznáte; my se klaníme tomu, co známe, protože spása přichází ze Židů."],[23,"Přichází však hodina, a už je tady, kdy se praví ctitelé budou klanět Otci v duchu a v pravdě. Právě takové totiž Otec hledá."],[24,"Bůh je duch a ti, kdo se mu klanějí, se mu musí klanět v duchu a v pravdě.“"],[25,"Žena mu řekla: „Vím, že přijde Mesiáš, zvaný Kristus. Až přijde, oznámí nám všechno.“"],[26,"Ježíš jí řekl: „Já jsem to, já, který s tebou mluvím.“"],[27,"Vtom se vrátili jeho učedníci a divili se, že mluví se ženou. Nikdo se ho však nezeptal: „Co od ní chceš?“ ani: „Proč s ní mluvíš?“"],[28,"Žena tam nechala svůj džbán, odešla do města a říkala lidem:"],[29,"„Pojďte se podívat na člověka, který mi řekl všechno, co jsem udělala. Není to snad Mesiáš?“"],[30,"Vyšli tedy z města a přicházeli k němu."],[31,"Mezitím ho učedníci prosili: „Mistře, najez se.“"],[32,"On jim však řekl: „Já mám k jídlu pokrm, o kterém vy nevíte.“"],[33,"Učedníci si mezi sebou říkali: „Přinesl mu snad někdo něco k jídlu?“"],[34,"Ježíš jim řekl: „Mým pokrmem je konat vůli toho, který mě poslal, a dokončit jeho dílo."],[35,"Vy říkáte: ‚Ještě čtyři měsíce a přijde žeň.‘ Já vám však říkám: Zvedněte oči a podívejte se na pole, už se bělají ke žni."],[36,"Ten, kdo žne, dostává odměnu a shromažďuje úrodu pro věčný život, aby se společně radovali ten, kdo rozsévá, i ten, kdo žne."],[37,"Tady platí pravdivé přísloví: ‚Jeden rozsévá a jiný žne.‘"],[38,"Poslal jsem vás sklízet tam, kde jste se nenamáhali. Jiní pracovali a vy vstupujete do výsledků jejich práce.“"],[39,"Mnoho Samařanů z toho města v něj uvěřilo kvůli svědectví té ženy: „Řekl mi všechno, co jsem udělala.“"],[40,"Když k němu Samařané přišli, prosili ho, aby u nich zůstal. Zůstal tam dva dny."],[41,"A ještě mnohem více jich uvěřilo kvůli jeho slovu."],[42,"Ženě pak říkali: „Teď už nevěříme jen kvůli tomu, cos nám vyprávěla. Sami jsme ho slyšeli a víme, že tento je skutečně Spasitel světa, Kristus.“"]]},{"title":"Uzdravení syna královského služebníka","range":"Jan 4,43–54","thoughts":[],"verses":[[43,"Po dvou dnech odtud odešel do Galileje."],[44,"Ježíš totiž sám dosvědčil, že prorok nemá ve své vlasti úctu."],[45,"Když přišel do Galileje, Galilejci ho přijali, protože viděli všechno, co během svátků udělal v Jeruzalémě; i oni totiž byli na svátcích."],[46,"Ježíš tedy znovu přišel do galilejské Kány, kde proměnil vodu ve víno. V Kafarnaum žil jeden královský služebník, jehož syn byl nemocný."],[47,"Když uslyšel, že Ježíš přišel z Judska do Galileje, šel za ním a prosil ho, aby sestoupil do Kafarnaa a uzdravil jeho syna, který už umíral."],[48,"Ježíš mu řekl: „Dokud neuvidíte znamení a zázraky, neuvěříte.“"],[49,"Královský služebník mu řekl: „Pane, pojď dřív, než moje dítě zemře.“"],[50,"Ježíš mu řekl: „Jdi, tvůj syn žije.“ Ten člověk uvěřil slovu, které mu Ježíš řekl, a vydal se na cestu."],[51,"Když byl ještě na cestě, potkali ho jeho služebníci a oznámili mu: „Tvůj syn žije.“"],[52,"Zeptal se jich, v kolik hodin se mu ulevilo. Odpověděli: „Včera v jednu hodinu odpoledne ho přestala horečka.“"],[53,"Otec poznal, že to bylo právě v tu hodinu, kdy mu Ježíš řekl: „Tvůj syn žije.“ A uvěřil on i celý jeho dům."],[54,"To bylo druhé znamení, které Ježíš udělal poté, co přišel z Judska do Galileje."]]}];

JOHN_SECTIONS["5"] = [{"title":"Uzdravení u rybníka Bethesda","range":"Jan 5,1–18","thoughts":[],"verses":[[1,"Potom byl židovský svátek a Ježíš vystoupil do Jeruzaléma."],[2,"V Jeruzalémě je u Ovčí brány rybník, hebrejsky zvaný Bethesda, který má pět sloupořadí."],[3,"V nich leželo veliké množství nemocných, slepých, chromých a ochrnutých, kteří čekali, až se voda pohne."],[4,"Anděl totiž čas od času sestupoval do rybníka a rozvířil vodu. Kdo po rozvíření vody vstoupil jako první, byl uzdraven z jakékoli nemoci, kterou trpěl."],[5,"Byl tam jeden člověk, který byl nemocný už třicet osm let."],[6,"Když ho Ježíš uviděl ležet a poznal, že je nemocný už dlouho, zeptal se ho: „Chceš být zdráv?“"],[7,"Nemocný mu odpověděl: „Pane, nemám nikoho, kdo by mě spustil do rybníka, když se voda rozvíří. Než se tam dostanu, sestoupí přede mnou někdo jiný.“"],[8,"Ježíš mu řekl: „Vstaň, vezmi své lehátko a choď.“"],[9,"Ten člověk byl ihned uzdraven, vzal své lehátko a chodil. Toho dne však byla sobota."],[10,"Židé proto uzdravenému řekli: „Je sobota, nesmíš nosit své lehátko.“"],[11,"On jim odpověděl: „Ten, který mě uzdravil, mi řekl: ‚Vezmi své lehátko a choď.‘“"],[12,"Zeptali se ho: „Kdo je ten člověk, který ti řekl: ‚Vezmi své lehátko a choď‘?“"],[13,"Uzdravený však nevěděl, kdo to byl, protože Ježíš se ztratil v zástupu, který tam byl."],[14,"Později ho Ježíš našel v chrámě a řekl mu: „Podívej, jsi zdráv. Už nehřeš, aby tě nepotkalo něco horšího.“"],[15,"Ten člověk odešel a oznámil Židům, že ho uzdravil Ježíš."],[16,"Proto Židé Ježíše pronásledovali a chtěli ho zabít, protože to udělal v sobotu."],[17,"Ježíš jim však odpověděl: „Můj Otec pracuje až dosud a i já pracuji.“"],[18,"Kvůli tomu ho Židé chtěli zabít ještě víc. Nejenže podle nich porušoval sobotu, ale také nazýval Boha svým Otcem, a tak se stavěl na roveň Bohu."]]},{"title":"Syn a Otec","range":"Jan 5,19–30","thoughts":[],"verses":[[19,"Ježíš jim odpověděl: „Amen, amen, říkám vám: Syn nemůže dělat nic sám od sebe, ale jen to, co vidí dělat Otce. Co dělá Otec, to stejně dělá i Syn."],[20,"Otec totiž miluje Syna a ukazuje mu všechno, co sám dělá. A ukáže mu ještě větší skutky, než jsou tyto, abyste žasli."],[21,"Jako Otec křísí mrtvé a dává jim život, tak i Syn dává život těm, kterým chce."],[22,"Otec totiž nikoho nesoudí, ale všechen soud svěřil Synu,"],[23,"aby všichni ctili Syna stejně, jako ctí Otce. Kdo nectí Syna, nectí ani Otce, který ho poslal."],[24,"Amen, amen, říkám vám: Kdo slyší mé slovo a věří tomu, který mě poslal, má věčný život a nepřijde na soud, ale přešel ze smrti do života."],[25,"Amen, amen, říkám vám: Přichází hodina, a už je tady, kdy mrtví uslyší hlas Božího Syna a ti, kdo ho uslyší, budou žít."],[26,"Jako má Otec život sám v sobě, tak dal i Synu, aby měl život sám v sobě."],[27,"Dal mu také moc vykonávat soud, protože je Syn člověka."],[28,"Nedivte se tomu, protože přichází hodina, kdy všichni, kdo jsou v hrobech, uslyší jeho hlas"],[29,"a vyjdou: ti, kdo konali dobro, k vzkříšení života, a ti, kdo konali zlo, k vzkříšení soudu."],[30,"Já sám od sebe nemohu dělat nic. Soudím podle toho, co slyším, a můj soud je spravedlivý, protože nehledám svou vůli, ale vůli Otce, který mě poslal."]]},{"title":"Svědectví o Ježíšovi","range":"Jan 5,31–47","thoughts":[],"verses":[[31,"„Kdybych vydával svědectví sám o sobě, moje svědectví by nebylo platné."],[32,"Je tu jiný, který o mně svědčí, a vím, že svědectví, které o mně vydává, je pravdivé."],[33,"Poslali jste k Janovi a on vydal svědectví pravdě."],[34,"Já však nepotřebuji svědectví od člověka. Říkám to kvůli vám, abyste byli zachráněni."],[35,"Jan byl hořící a zářící lampou a vy jste se na čas chtěli radovat v jeho světle."],[36,"Já však mám větší svědectví než Jan: skutky, které mi Otec dal, abych je dokončil. Právě skutky, které konám, o mně svědčí, že mě Otec poslal."],[37,"A Otec, který mě poslal, sám o mně vydal svědectví. Jeho hlas jste nikdy neslyšeli ani jeho tvář neviděli."],[38,"Jeho slovo ve vás nezůstává, protože nevěříte tomu, koho poslal."],[39,"Zkoumáte Písma, protože se domníváte, že v nich máte věčný život. A právě ona svědčí o mně."],[40,"Vy však nechcete přijít ke mně, abyste měli život."],[41,"Slávu od lidí nepřijímám."],[42,"Znám vás však a vím, že v sobě nemáte lásku k Bohu."],[43,"Přišel jsem ve jménu svého Otce, a nepřijímáte mě. Kdyby někdo jiný přišel ve svém vlastním jménu, toho přijmete."],[44,"Jak můžete věřit, když přijímáte slávu jeden od druhého, ale slávu, která přichází od jediného Boha, nehledáte?"],[45,"Nemyslete si, že vás budu u Otce obviňovat já. Obviňuje vás Mojžíš, v něhož skládáte svou naději."],[46,"Kdybyste totiž věřili Mojžíšovi, věřili byste i mně, protože on psal o mně."],[47,"Jestliže však nevěříte jeho spisům, jak uvěříte mým slovům?“"]]}];

JOHN_SECTIONS["6"] = [{"title":"Nasycení pěti tisíc","range":"Jan 6,1–15","thoughts":[],"verses":[[1,"Potom Ježíš odešel na druhý břeh Galilejského, neboli Tiberiadského moře."],[2,"Šel za ním veliký zástup, protože lidé viděli znamení, která dělal na nemocných."],[3,"Ježíš vystoupil na horu a tam se posadil se svými učedníky."],[4,"Blížily se židovské Velikonoce."],[5,"Ježíš zvedl oči, uviděl veliký zástup, který k němu přicházel, a zeptal se Filipa: „Kde nakoupíme chleba, aby se tito lidé najedli?“"],[6,"Řekl to, aby Filipa vyzkoušel; sám totiž věděl, co udělá."],[7,"Filip mu odpověděl: „Ani chleba za dvě stě denárů by nestačilo, aby každý dostal aspoň trochu.“"],[8,"Jeden z jeho učedníků, Ondřej, bratr Šimona Petra, mu řekl:"],[9,"„Je tu jeden chlapec, který má pět ječných chlebů a dvě ryby. Ale co je to pro tolik lidí?“"],[10,"Ježíš řekl: „Ať se lidé posadí.“ Na tom místě bylo hodně trávy. Posadilo se tam asi pět tisíc mužů."],[11,"Ježíš vzal chleby, vzdal díky a rozdával je sedícím; stejně tak i ryby, kolik kdo chtěl."],[12,"Když se všichni nasytili, řekl svým učedníkům: „Posbírejte zbylé kousky, aby nic nepřišlo nazmar.“"],[13,"Posbírali je tedy a naplnili dvanáct košů kousky, které zbyly z pěti ječných chlebů po těch, kdo jedli."],[14,"Když lidé viděli znamení, které Ježíš udělal, říkali: „To je skutečně ten Prorok, který měl přijít na svět.“"],[15,"Ježíš poznal, že se ho chtějí zmocnit a udělat ho králem, a proto se znovu uchýlil sám na horu."]]},{"title":"Ježíš kráčí po moři","range":"Jan 6,16–21","thoughts":[],"verses":[[16,"Když nastal večer, jeho učedníci sestoupili k moři."],[17,"Nastoupili do lodi a plavili se přes moře do Kafarnaa. Už byla tma a Ježíš k nim ještě nepřišel."],[18,"Moře se začalo vzdouvat, protože foukal silný vítr."],[19,"Když urazili asi pětadvacet až třicet honů, uviděli Ježíše, jak kráčí po moři a přibližuje se k lodi. Dostali strach."],[20,"On jim však řekl: „To jsem já, nebojte se.“"],[21,"Rádi ho tedy vzali do lodi a loď se hned dostala ke břehu, ke kterému mířili."]]},{"title":"Ježíš, chléb života","range":"Jan 6,22–59","thoughts":[],"verses":[[22,"Druhého dne si zástup, který zůstal na druhém břehu, uvědomil, že tam byla jen jedna loď a že Ježíš do ní se svými učedníky nenastoupil, ale učedníci odpluli sami."],[23,"Mezitím připluly od Tiberiady jiné lodě blízko místa, kde lidé jedli chléb poté, co Pán vzdal díky."],[24,"Když zástup viděl, že tam Ježíš ani jeho učedníci nejsou, nastoupili také do lodí a přijeli do Kafarnaa hledat Ježíše."],[25,"Když ho našli na druhém břehu, zeptali se ho: „Mistře, kdy ses sem dostal?“"],[26,"Ježíš jim odpověděl: „Amen, amen, říkám vám: Hledáte mě ne proto, že jste viděli znamení, ale proto, že jste jedli z chlebů a nasytili jste se."],[27,"Neusilujte o pokrm, který pomíjí, ale o pokrm, který zůstává k věčnému životu a který vám dá Syn člověka. Jeho totiž Bůh Otec potvrdil.“"],[28,"Zeptali se ho: „Co máme dělat, abychom konali Boží skutky?“"],[29,"Ježíš jim odpověděl: „Boží skutek je právě toto: abyste věřili v toho, kterého Bůh poslal.“"],[30,"Řekli mu: „Jaké znamení tedy uděláš, abychom ho viděli a uvěřili ti? Co vykonáš?"],[31,"Naši otcové jedli na poušti manu, jak je napsáno: ‚Dal jim jíst chléb z nebe.‘“"],[32,"Ježíš jim řekl: „Amen, amen, říkám vám: Nebyl to Mojžíš, kdo vám dal chléb z nebe. Můj Otec vám dává pravý chléb z nebe."],[33,"Boží chléb je totiž ten, který sestupuje z nebe a dává život světu.“"],[34,"Řekli mu: „Pane, dávej nám tento chléb pořád.“"],[35,"Ježíš jim řekl: „Já jsem chléb života. Kdo přichází ke mně, nebude hladovět, a kdo ve mě věří, nebude nikdy žíznit."],[36,"Ale už jsem vám řekl: viděli jste mě, a přesto nevěříte."],[37,"Všichni, které mi Otec dává, ke mně přijdou, a toho, kdo ke mně přijde, nikdy nevyženu ven."],[38,"Sestoupil jsem z nebe ne proto, abych konal svou vůli, ale vůli toho, který mě poslal."],[39,"A vůle Otce, který mě poslal, je, abych neztratil nikoho z těch, které mi dal, ale abych je vzkřísil v poslední den."],[40,"Vůle toho, který mě poslal, je také to, aby každý, kdo vidí Syna a věří v něj, měl věčný život. A já ho vzkřísím v poslední den.“"],[41,"Židé proti němu začali reptat, protože řekl: „Já jsem chléb, který sestoupil z nebe.“"],[42,"Říkali: „Copak to není Ježíš, syn Josefův? Vždyť známe jeho otce i matku. Jak může říkat: ‚Sestoupil jsem z nebe‘?“"],[43,"Ježíš jim odpověděl: „Nereptejte mezi sebou."],[44,"Nikdo nemůže přijít ke mně, pokud ho nepřitáhne Otec, který mě poslal; a já ho vzkřísím v poslední den."],[45,"V Prorocích je napsáno: ‚Všichni budou vyučeni Bohem.‘ Každý, kdo slyšel Otce a přijal jeho učení, přichází ke mně."],[46,"Ne že by Otce někdo viděl; Otce viděl jen ten, který je od Boha."],[47,"Amen, amen, říkám vám: Kdo ve mě věří, má věčný život."],[48,"Já jsem chléb života."],[49,"Vaši otcové jedli na poušti manu, a přesto zemřeli."],[50,"Toto je chléb, který sestupuje z nebe, aby ten, kdo z něj jí, nezemřel."],[51,"Já jsem ten živý chléb, který sestoupil z nebe. Kdo bude jíst tento chléb, bude žít navěky. A chléb, který já dám za život světa, je mé tělo.“"],[52,"Židé se mezi sebou začali přít: „Jak nám tento člověk může dát jíst své tělo?“"],[53,"Ježíš jim řekl: „Amen, amen, říkám vám: Nebudete-li jíst tělo Syna člověka a pít jeho krev, nemáte v sobě život."],[54,"Kdo jí mé tělo a pije mou krev, má věčný život a já ho vzkřísím v poslední den."],[55,"Mé tělo je totiž skutečný pokrm a má krev je skutečný nápoj."],[56,"Kdo jí mé tělo a pije mou krev, zůstává ve mně a já v něm."],[57,"Jako mě poslal živý Otec a já žiji skrze Otce, tak i ten, kdo jí mě, bude žít skrze mne."],[58,"Toto je chléb, který sestoupil z nebe. Není jako ten, který jedli vaši otcové, a zemřeli. Kdo jí tento chléb, bude žít navěky.“"],[59,"To řekl, když učil v synagoze v Kafarnaum."]]},{"title":"Mnozí učedníci odcházejí","range":"Jan 6,60–71","thoughts":[],"verses":[[60,"Když to slyšeli mnozí z jeho učedníků, řekli: „To je tvrdá řeč. Kdo ji může poslouchat?“"],[61,"Ježíš věděl, že kvůli tomu jeho učedníci reptají, a řekl jim: „To vás pohoršuje?"],[62,"Co teprve, až uvidíte Syna člověka vystupovat tam, kde byl předtím?"],[63,"Duch dává život, tělo samo nic neprospívá. Slova, která jsem vám řekl, jsou Duch a život."],[64,"Někteří z vás však nevěří.“ Ježíš totiž od začátku věděl, kdo nevěří a kdo ho zradí."],[65,"A řekl: „Proto jsem vám řekl, že nikdo nemůže přijít ke mně, není-li mu to dáno od mého Otce.“"],[66,"Od té chvíle se mnozí z jeho učedníků odvrátili a už s ním nechodili."],[67,"Ježíš se tedy zeptal Dvanácti: „Chcete snad odejít i vy?“"],[68,"Šimon Petr mu odpověděl: „Pane, ke komu bychom šli? Ty máš slova věčného života."],[69,"My jsme uvěřili a poznali, že ty jsi Mesiáš, Syn živého Boha.“"],[70,"Ježíš jim odpověděl: „Nevybral jsem si vás Dvanáct? A přece je jeden z vás ďábel.“"],[71,"Mluvil o Jidáši, synu Šimona Iškariotského. Ten ho měl zradit, přestože byl jedním z Dvanácti."]]}];

JOHN_SECTIONS["7"] = [{"title":"Ježíš a jeho bratři","range":"Jan 7,1–9","thoughts":[],"verses":[[1,"Potom Ježíš chodil po Galileji. Nechtěl totiž pobývat v Judsku, protože ho tam Židé chtěli zabít."],[2,"Blížil se židovský svátek stánků."],[3,"Jeho bratři mu řekli: „Odejdi odsud do Judska, aby i tvoji učedníci viděli skutky, které děláš."],[4,"Nikdo přece nedělá něco v skrytu, když chce být veřejně známý. Když děláš takové věci, ukaž se světu.“"],[5,"Ani jeho bratři totiž v něj nevěřili."],[6,"Ježíš jim řekl: „Můj čas ještě nepřišel, ale váš čas je vždycky vhodný."],[7,"Vás svět nemůže nenávidět, ale mě nenávidí, protože o něm svědčím, že jeho skutky jsou zlé."],[8,"Jděte na ten svátek vy. Já na tento svátek ještě nepůjdu, protože můj čas se ještě nenaplnil.“"],[9,"Když jim to řekl, zůstal v Galileji."]]},{"title":"Ježíš na slavnosti stánků","range":"Jan 7,10–24","thoughts":[],"verses":[[10,"Když jeho bratři odešli na svátek, vydal se tam i on, ale ne veřejně, nýbrž jakoby skrytě."],[11,"Židé ho během svátku hledali a ptali se: „Kde je?“"],[12,"Mezi zástupy se o něm hodně mluvilo. Někteří říkali: „Je dobrý.“ Jiní však tvrdili: „Není, svádí lid.“"],[13,"Nikdo o něm ale nemluvil veřejně, protože se báli Židů."],[14,"Asi v polovině svátku vstoupil Ježíš do chrámu a začal učit."],[15,"Židé se divili a říkali: „Jak to, že tento člověk zná Písma, když se neučil?“"],[16,"Ježíš jim odpověděl: „Mé učení není moje, ale toho, který mě poslal."],[17,"Kdo chce konat jeho vůli, pozná, zda toto učení pochází od Boha, nebo zda mluvím sám ze sebe."],[18,"Kdo mluví sám ze sebe, hledá vlastní slávu. Kdo však hledá slávu toho, který ho poslal, je pravdivý a není v něm nepravost."],[19,"Nedal vám snad Mojžíš Zákon? A přesto nikdo z vás Zákon neplní. Proč mě chcete zabít?“"],[20,"Zástup odpověděl: „Jsi posedlý! Kdo tě chce zabít?“"],[21,"Ježíš jim řekl: „Udělal jsem jeden skutek a všichni se nad tím podivujete."],[22,"Mojžíš vám dal obřízku — i když ve skutečnosti nepochází od Mojžíše, ale od otců — a vy obřezáváte člověka i v sobotu."],[23,"Jestliže člověk přijímá obřízku v sobotu, aby nebyl porušen Mojžíšův zákon, proč se na mě hněváte, že jsem v sobotu uzdravil celého člověka?"],[24,"Nesuďte podle zdání, ale suďte spravedlivě.“"]]},{"title":"Spor o Ježíšův původ","range":"Jan 7,25–36","thoughts":[],"verses":[[25,"Někteří obyvatelé Jeruzaléma říkali: „Není to ten, kterého chtějí zabít?"],[26,"A podívejte, mluví veřejně a nic mu neříkají. Snad už přední muži opravdu poznali, že je to Mesiáš?"],[27,"Jenže o tomto člověku víme, odkud je. Až přijde Mesiáš, nikdo nebude vědět, odkud je.“"],[28,"Ježíš při vyučování v chrámě hlasitě zvolal: „Ano, znáte mě a víte, odkud jsem. Nepřišel jsem však sám od sebe. Ten, který mě poslal, je pravdivý, ale vy ho neznáte."],[29,"Já ho znám, protože jsem od něj a on mě poslal.“"],[30,"Chtěli ho tedy zatknout, ale nikdo na něj nevztáhl ruku, protože jeho hodina ještě nepřišla."],[31,"Mnozí ze zástupu však v něj uvěřili a říkali: „Až přijde Mesiáš, udělá snad více znamení než tento?“"],[32,"Farizeové zaslechli, co si o něm lidé šeptají, a spolu s velekněžími poslali chrámovou stráž, aby ho zatkla."],[33,"Ježíš řekl: „Ještě krátký čas jsem s vámi a potom odejdu k tomu, který mě poslal."],[34,"Budete mě hledat, ale nenajdete mě. A tam, kde budu já, vy přijít nemůžete.“"],[35,"Židé si mezi sebou říkali: „Kam chce odejít, že ho nenajdeme? Chce snad jít k Židům rozptýleným mezi pohany a učit pohany?"],[36,"Co znamenají ta jeho slova: ‚Budete mě hledat, ale nenajdete mě, a tam, kde budu já, vy přijít nemůžete‘?“"]]},{"title":"Proudy živé vody","range":"Jan 7,37–39","thoughts":[],"verses":[[37,"V poslední, veliký den svátku Ježíš povstal a hlasitě zvolal: „Jestliže někdo žízní, ať přijde ke mně a pije."],[38,"Kdo ve mě věří, z jeho nitra, jak říká Písmo, poplynou proudy živé vody.“"],[39,"Tím mluvil o Duchu, kterého měli přijmout ti, kdo v něj věří. Duch svatý totiž ještě nebyl dán, protože Ježíš ještě nebyl oslaven."]]},{"title":"Rozdělení mezi lidmi","range":"Jan 7,40–53","thoughts":[],"verses":[[40,"Když někteří ze zástupu slyšeli tato slova, říkali: „To je skutečně ten Prorok.“"],[41,"Jiní říkali: „To je Mesiáš.“ Další však namítali: „Mesiáš snad přijde z Galileje?"],[42,"Neříká Písmo, že Mesiáš přijde z Davidova potomstva a z Betléma, vesnice, odkud byl David?“"],[43,"Kvůli němu tedy vznikl v zástupu rozkol."],[44,"Někteří ho chtěli zatknout, ale nikdo na něj nevztáhl ruku."],[45,"Chrámová stráž se vrátila k velekněžím a farizeům. Ti se jich zeptali: „Proč jste ho nepřivedli?“"],[46,"Stráž odpověděla: „Nikdy žádný člověk nemluvil jako tento.“"],[47,"Farizeové jim řekli: „Tak jste se nechali svést i vy?"],[48,"Uvěřil snad v něj někdo z předních mužů nebo z farizeů?"],[49,"Jen ten zástup, který nezná Zákon. Ti jsou prokletí.“"],[50,"Nikodém, ten, který k Ježíšovi přišel v noci a byl jedním z nich, jim řekl:"],[51,"„Odsuzuje snad náš Zákon člověka dříve, než ho vyslechne a zjistí, co udělal?“"],[52,"Odpověděli mu: „Nejsi snad také z Galileje? Zkoumej a uvidíš, že z Galileje žádný prorok nepovstal.“"],[53,"Potom se každý vrátil domů."]]}];

JOHN_SECTIONS["8"] = [{"title":"Žena přistižená při cizoložství","range":"Jan 8,1–11","thoughts":[],"verses":[[1,"Ježíš odešel na Olivovou horu."],[2,"Brzy ráno znovu přišel do chrámu. Všechen lid se k němu shromáždil, a tak se posadil a učil je."],[3,"Učitelé Zákona a farizeové k němu přivedli ženu přistiženou při cizoložství a postavili ji doprostřed."],[4,"Řekli mu: „Mistře, tato žena byla přistižena přímo při cizoložství."],[5,"Mojžíš nám v Zákoně přikázal takové ženy kamenovat. Co říkáš ty?“"],[6,"Říkali to proto, aby ho zkoušeli a mohli ho z něčeho obžalovat. Ježíš se však sklonil a psal prstem po zemi."],[7,"Když se ho nepřestávali ptát, narovnal se a řekl jim: „Kdo z vás je bez hříchu, ať po ní hodí kamenem jako první.“"],[8,"Potom se znovu sklonil a psal po zemi."],[9,"Když to uslyšeli a jejich svědomí je usvědčovalo, začali jeden po druhém odcházet, od nejstarších až po poslední. Ježíš zůstal sám a žena stála uprostřed."],[10,"Ježíš se narovnal a když kromě ženy nikoho neviděl, řekl jí: „Ženo, kde jsou ti, kdo tě obviňovali? Nikdo tě neodsoudil?“"],[11,"Odpověděla: „Nikdo, Pane.“ Ježíš jí řekl: „Ani já tě neodsuzuji. Jdi a od této chvíle už nehřeš.“"]]},{"title":"Ježíš, světlo světa","range":"Jan 8,12–20","thoughts":[],"verses":[[12,"Ježíš k nim znovu promluvil: „Já jsem světlo světa. Kdo mě následuje, nebude chodit ve tmě, ale bude mít světlo života.“"],[13,"Farizeové mu řekli: „Ty vydáváš svědectví sám o sobě, takže tvé svědectví není platné.“"],[14,"Ježíš jim odpověděl: „I když vydávám svědectví sám o sobě, mé svědectví je pravdivé, protože vím, odkud jsem přišel a kam jdu. Vy však nevíte, odkud přicházím ani kam jdu."],[15,"Vy soudíte podle lidských měřítek; já nikoho nesoudím."],[16,"A i kdybych soudil, můj soud je pravdivý, protože nejsem sám: jsem tu já a Otec, který mě poslal."],[17,"Ve vašem Zákoně je přece napsáno, že svědectví dvou lidí je platné."],[18,"Svědčím o sobě já a svědčí o mně také Otec, který mě poslal.“"],[19,"Zeptali se ho: „Kde je tvůj Otec?“ Ježíš odpověděl: „Neznáte ani mě, ani mého Otce. Kdybyste znali mě, znali byste i mého Otce.“"],[20,"Tato slova řekl u chrámové pokladnice, když učil v chrámě. Nikdo ho však nezatkl, protože jeho hodina ještě nepřišla."]]},{"title":"Kam já jdu, vy nemůžete přijít","range":"Jan 8,21–30","thoughts":[],"verses":[[21,"Ježíš jim znovu řekl: „Já odcházím. Budete mě hledat a zemřete ve svém hříchu. Tam, kam jdu já, vy přijít nemůžete.“"],[22,"Židé si říkali: „Chce se snad zabít, když říká: ‚Tam, kam jdu já, vy přijít nemůžete‘?“"],[23,"Ježíš jim řekl: „Vy jste zdola, já jsem shůry. Vy jste z tohoto světa, já z tohoto světa nejsem."],[24,"Proto jsem vám řekl, že zemřete ve svých hříších. Jestliže totiž neuvěříte, že já jsem, zemřete ve svých hříších.“"],[25,"Zeptali se ho: „Kdo jsi?“ Ježíš jim odpověděl: „To, co vám říkám od začátku."],[26,"Mám o vás ještě mnoho co říci a soudit, ale ten, který mě poslal, je pravdivý a já světu říkám to, co jsem slyšel od něj.“"],[27,"Nepochopili, že k nim mluví o Otci."],[28,"Ježíš jim tedy řekl: „Až vyzdvihnete Syna člověka, tehdy poznáte, že já jsem a že nic nedělám sám od sebe, ale mluvím tak, jak mě naučil Otec."],[29,"Ten, který mě poslal, je se mnou. Otec mě nenechal samotného, protože vždy dělám to, co se mu líbí.“"],[30,"Když toto říkal, mnozí v něj uvěřili."]]},{"title":"Pravda vás osvobodí","range":"Jan 8,31–47","thoughts":[],"verses":[[31,"Ježíš řekl Židům, kteří mu uvěřili: „Jestliže zůstanete v mém slovu, budete opravdu mými učedníky."],[32,"Poznáte pravdu a pravda vás osvobodí.“"],[33,"Odpověděli mu: „Jsme Abrahamovi potomci a nikdy jsme nikomu nesloužili. Jak můžeš říkat: ‚Budete svobodní‘?“"],[34,"Ježíš jim odpověděl: „Amen, amen, říkám vám: Každý, kdo páchá hřích, je otrokem hříchu."],[35,"Otrok nezůstává v domě navždy; Syn v něm zůstává navždy."],[36,"Jestliže vás tedy Syn osvobodí, budete skutečně svobodní."],[37,"Vím, že jste Abrahamovi potomci. Přesto mě chcete zabít, protože mé slovo ve vás nemá místo."],[38,"Já mluvím o tom, co jsem viděl u svého Otce, a vy děláte to, co jste viděli u svého otce.“"],[39,"Odpověděli mu: „Naším otcem je Abraham.“ Ježíš jim řekl: „Kdybyste byli Abrahamovy děti, dělali byste Abrahamovy skutky."],[40,"Teď mě však chcete zabít, člověka, který vám řekl pravdu, již slyšel od Boha. To Abraham nedělal."],[41,"Vy děláte skutky svého otce.“ Řekli mu: „My jsme se nenarodili ze smilstva. Máme jednoho Otce: Boha.“"],[42,"Ježíš jim řekl: „Kdyby byl Bůh vaším Otcem, milovali byste mě, protože jsem vyšel od Boha a přišel jsem od něj. Nepřišel jsem sám od sebe; on mě poslal."],[43,"Proč nerozumíte tomu, co říkám? Protože nejste schopni naslouchat mému slovu."],[44,"Vy máte za otce ďábla a chcete plnit touhy svého otce. On byl vrahem od počátku a nezůstal v pravdě, protože v něm pravda není. Když mluví lež, mluví z toho, co je mu vlastní, protože je lhář a otec lži."],[45,"Mně však nevěříte právě proto, že říkám pravdu."],[46,"Kdo z vás mě může usvědčit z hříchu? Jestliže říkám pravdu, proč mi nevěříte?"],[47,"Kdo je z Boha, slyší Boží slova. Vy je neslyšíte právě proto, že z Boha nejste.“"]]},{"title":"Ježíš a Abraham","range":"Jan 8,48–59","thoughts":[],"verses":[[48,"Židé mu odpověděli: „Neříkáme snad správně, že jsi Samařan a že máš démona?“"],[49,"Ježíš odpověděl: „Nemám démona. Ctím svého Otce, ale vy mě znevažujete."],[50,"Já však nehledám svou vlastní slávu. Je tu ten, který ji hledá a soudí."],[51,"Amen, amen, říkám vám: Kdo zachovává mé slovo, nikdy neuvidí smrt.“"],[52,"Židé mu řekli: „Teď už víme, že máš démona. Abraham zemřel a proroci také, a ty říkáš: ‚Kdo zachovává mé slovo, nikdy neokusí smrt.‘"],[53,"Jsi snad větší než náš otec Abraham, který zemřel? Zemřeli i proroci. Za koho se vlastně vydáváš?“"],[54,"Ježíš odpověděl: „Kdybych oslavoval sám sebe, má sláva by nic neznamenala. Oslavuje mě můj Otec, o němž říkáte, že je vaším Bohem."],[55,"Vy jste ho nepoznali, ale já ho znám. Kdybych řekl, že ho neznám, byl bych lhář jako vy. Já ho však znám a zachovávám jeho slovo."],[56,"Váš otec Abraham se radoval, že uvidí můj den. Uviděl ho a zaradoval se.“"],[57,"Židé mu řekli: „Ještě ti není ani padesát let, a viděl jsi Abrahama?“"],[58,"Ježíš jim řekl: „Amen, amen, říkám vám: Dříve než Abraham byl, já jsem.“"],[59,"Tehdy zvedli kameny, aby je po něm házeli. Ježíš se však skryl, prošel mezi nimi, vyšel z chrámu a odešel."]]}];

JOHN_SECTIONS["9"] = [{"title":"Uzdravení slepého od narození","range":"Jan 9,1–12","thoughts":[],"verses":[[1,"Když Ježíš procházel kolem, uviděl člověka, který byl slepý od narození."],[2,"Jeho učedníci se ho zeptali: „Mistře, kdo zhřešil, on, nebo jeho rodiče, že se narodil slepý?“"],[3,"Ježíš odpověděl: „Nezhřešil ani on, ani jeho rodiče. Je to proto, aby se na něm ukázaly Boží skutky."],[4,"Dokud je den, musím konat skutky toho, který mě poslal. Přichází noc, kdy nikdo nebude moci pracovat."],[5,"Dokud jsem na světě, jsem světlo světa.“"],[6,"Když to řekl, plivl na zem, udělal ze slin bláto a potřel tím blátem oči slepého."],[7,"Řekl mu: „Jdi se umýt v rybníku Siloe,“ což znamená Poslaný. Muž tedy odešel, umyl se a vrátil se s očima otevřenýma."],[8,"Sousedé a ti, kteří ho dříve vídali jako slepého žebráka, se ptali: „Není to ten, který sedával a žebral?“"],[9,"Jedni říkali: „Je to on.“ Jiní: „Ne, jen se mu podobá.“ On však říkal: „Jsem to já.“"],[10,"Ptali se ho tedy: „Jak se ti otevřely oči?“"],[11,"Odpověděl: „Člověk jménem Ježíš udělal bláto, potřel mi oči a řekl mi: ‚Jdi k rybníku Siloe a umyj se.‘ Šel jsem tedy, umyl jsem se a začal jsem vidět.“"],[12,"Zeptali se ho: „Kde je?“ Odpověděl: „Nevím.“"]]},{"title":"Farizeové vyslýchají uzdraveného","range":"Jan 9,13–34","thoughts":[],"verses":[[13,"Přivedli toho, který byl dříve slepý, k farizeům."],[14,"Byla totiž sobota, když Ježíš udělal bláto a otevřel mu oči."],[15,"Farizeové se ho znovu ptali, jak začal vidět. Odpověděl jim: „Položil mi na oči bláto, umyl jsem se a vidím.“"],[16,"Někteří farizeové říkali: „Ten člověk není od Boha, protože nezachovává sobotu.“ Jiní však říkali: „Jak by mohl hříšný člověk dělat taková znamení?“ A vznikl mezi nimi rozkol."],[17,"Znovu se tedy zeptali toho, který byl slepý: „Co o něm říkáš ty, když ti otevřel oči?“ Odpověděl: „Je to prorok.“"],[18,"Židé stále nevěřili, že byl slepý a začal vidět, dokud si nezavolali jeho rodiče."],[19,"Zeptali se jich: „Je toto váš syn, o kterém říkáte, že se narodil slepý? Jak to, že teď vidí?“"],[20,"Jeho rodiče odpověděli: „Víme, že je to náš syn a že se narodil slepý."],[21,"Jak je ale možné, že teď vidí, to nevíme. A nevíme ani, kdo mu otevřel oči. Je dospělý, zeptejte se jeho; může mluvit sám za sebe.“"],[22,"Jeho rodiče to řekli proto, že se báli Židů. Ti se totiž už dohodli, že kdo vyzná Ježíše jako Mesiáše, bude vyloučen ze synagogy."],[23,"Proto jeho rodiče řekli: „Je dospělý, zeptejte se jeho.“"],[24,"Zavolali tedy podruhé člověka, který býval slepý, a řekli mu: „Vzdej slávu Bohu. My víme, že ten člověk je hříšník.“"],[25,"On odpověděl: „Jestli je hříšník, to nevím. Jedno však vím: byl jsem slepý, a teď vidím.“"],[26,"Znovu se ho zeptali: „Co ti udělal? Jak ti otevřel oči?“"],[27,"Odpověděl jim: „Už jsem vám to řekl, ale neposlouchali jste. Proč to chcete slyšet znovu? Chcete se snad i vy stát jeho učedníky?“"],[28,"Začali mu nadávat: „Ty jsi jeho učedník. My jsme Mojžíšovi učedníci."],[29,"Víme, že k Mojžíšovi mluvil Bůh. O tomto člověku však nevíme, odkud je.“"],[30,"Ten muž jim odpověděl: „Právě to je podivné: vy nevíte, odkud je, a přitom mi otevřel oči."],[31,"Víme přece, že Bůh hříšníky nevyslýchá, ale vyslyší toho, kdo ho ctí a koná jeho vůli."],[32,"Od nepaměti nebylo slyšet, že by někdo otevřel oči člověku slepému od narození."],[33,"Kdyby tento člověk nebyl od Boha, nemohl by udělat nic.“"],[34,"Odpověděli mu: „Narodil ses celý v hříších, a ty nás chceš poučovat?“ A vyhnali ho ven."]]},{"title":"Duchovní slepota","range":"Jan 9,35–41","thoughts":[],"verses":[[35,"Ježíš uslyšel, že ho vyhnali. Když ho našel, zeptal se ho: „Věříš v Božího Syna?“"],[36,"Muž odpověděl: „Kdo to je, Pane, abych v něj mohl uvěřit?“"],[37,"Ježíš mu řekl: „Už jsi ho viděl. Je to ten, který s tebou právě mluví.“"],[38,"Muž řekl: „Věřím, Pane,“ a poklonil se mu."],[39,"Ježíš řekl: „Přišel jsem na tento svět k soudu, aby ti, kdo nevidí, viděli, a ti, kdo vidí, oslepli.“"],[40,"Někteří farizeové, kteří byli s ním, to slyšeli a zeptali se ho: „Jsme snad slepí i my?“"],[41,"Ježíš jim řekl: „Kdybyste byli slepí, neměli byste hřích. Vy však říkáte: ‚Vidíme.‘ Proto váš hřích zůstává."]]}];

JOHN_SECTIONS["10"] = [{"title":"Dobrý pastýř","range":"Jan 10,1–21","thoughts":[],"verses":[[1,"„Amen, amen, říkám vám: Kdo nevchází do ovčince dveřmi, ale leze dovnitř jinudy, je zloděj a lupič."],[2,"Kdo však vchází dveřmi, je pastýř ovcí."],[3,"Tomu vrátný otevře. Ovce slyší jeho hlas, on volá své vlastní ovce jménem a vyvádí je ven."],[4,"Když své ovce vyvede, jde před nimi a ovce ho následují, protože znají jeho hlas."],[5,"Za cizím člověkem nepůjdou, ale utečou od něj, protože hlas cizích neznají.“"],[6,"Ježíš jim řekl toto přirovnání, ale oni nepochopili, co jim tím chce říct."],[7,"Ježíš jim tedy znovu řekl: „Amen, amen, říkám vám: Já jsem dveře k ovcím."],[8,"Všichni, kdo přišli přede mnou, jsou zloději a lupiči, ale ovce je neposlouchaly."],[9,"Já jsem dveře. Kdo vejde skrze mne, bude zachráněn; bude vcházet i vycházet a najde pastvu."],[10,"Zloděj přichází jen proto, aby kradl, zabíjel a ničil. Já jsem přišel, aby měly život a měly ho v hojnosti."],[11,"Já jsem dobrý pastýř. Dobrý pastýř dává svůj život za ovce."],[12,"Nájemník, který není pastýřem a ovce mu nepatří, když vidí přicházet vlka, ovce opustí a uteče. Vlk je pak uchvacuje a rozhání."],[13,"Nájemník utíká, protože je jen nájemník a na ovcích mu nezáleží."],[14,"Já jsem dobrý pastýř. Znám své ovce a mé ovce znají mě,"],[15,"tak jako mě zná Otec a já znám Otce. A svůj život dávám za ovce."],[16,"Mám i jiné ovce, které nejsou z tohoto ovčince. I ty musím přivést; budou poslouchat můj hlas a bude jeden ovčinec a jeden pastýř."],[17,"Proto mě Otec miluje, že dávám svůj život, abych ho znovu přijal."],[18,"Nikdo mi ho nebere; dávám ho sám od sebe. Mám moc ho dát a mám moc ho znovu přijmout. Toto přikázání jsem přijal od svého Otce.“"],[19,"Kvůli těmto slovům mezi Židy znovu vznikl rozkol."],[20,"Mnozí z nich říkali: „Má démona a blázní. Proč ho posloucháte?“"],[21,"Jiní říkali: „To nejsou slova člověka posedlého démonem. Může snad démon otevírat oči slepým?“"]]},{"title":"Ježíš o svém vztahu k Otci","range":"Jan 10,22–39","thoughts":[],"verses":[[22,"V Jeruzalémě se slavila slavnost Posvěcení chrámu. Byla zima."],[23,"Ježíš se procházel v chrámě v Šalomounově sloupoví."],[24,"Židé ho obklopili a řekli mu: „Jak dlouho nás budeš držet v nejistotě? Jestliže jsi Mesiáš, řekni nám to otevřeně.“"],[25,"Ježíš jim odpověděl: „Řekl jsem vám to, ale nevěříte. Skutky, které konám ve jménu svého Otce, o mně vydávají svědectví."],[26,"Vy však nevěříte, protože nepatříte k mým ovcím, jak jsem vám řekl."],[27,"Mé ovce slyší můj hlas, já je znám a ony mě následují."],[28,"Dávám jim věčný život. Nikdy nezahynou a nikdo je nevytrhne z mé ruky."],[29,"Můj Otec, který mi je dal, je větší než všichni a nikdo je nemůže vytrhnout z ruky mého Otce."],[30,"Já a Otec jsme jedno.“"],[31,"Židé znovu zvedli kameny, aby ho ukamenovali."],[32,"Ježíš jim řekl: „Ukázal jsem vám mnoho dobrých skutků od svého Otce. Za který z nich mě chcete kamenovat?“"],[33,"Židé mu odpověděli: „Nekamenujeme tě za dobrý skutek, ale za rouhání: jsi člověk, a děláš ze sebe Boha.“"],[34,"Ježíš jim odpověděl: „Není snad ve vašem Zákoně napsáno: ‚Já jsem řekl: Jste bohové‘?"],[35,"Jestliže Písmo nazvalo bohy ty, ke kterým přišlo Boží slovo — a Písmo nemůže být zrušeno —"],[36,"proč říkáte tomu, kterého Otec posvětil a poslal na svět: ‚Rouháš se,‘ protože jsem řekl: ‚Jsem Boží Syn‘?"],[37,"Jestliže nekonám skutky svého Otce, nevěřte mi."],[38,"Jestliže je však konám, pak i když nevěříte mně, věřte těm skutkům, abyste poznali a uvěřili, že Otec je ve mně a já v něm.“"],[39,"Znovu se ho pokoušeli zatknout, ale unikl jim z rukou."]]},{"title":"Za Jordánem","range":"Jan 10,40–42","thoughts":[],"verses":[[40,"Ježíš znovu odešel za Jordán na místo, kde Jan zpočátku křtil, a zůstal tam."],[41,"Přicházelo k němu mnoho lidí a říkali: „Jan sice neudělal žádné znamení, ale všechno, co o tomto člověku řekl, bylo pravdivé.“"],[42,"A mnozí tam v Ježíše uvěřili."]]}];

JOHN_SECTIONS["11"] = [{"title":"Smrt Lazara","range":"Jan 11,1–16","thoughts":[],"verses":[[1,"Byl nemocný jeden muž jménem Lazar z Betanie, vesnice, kde žily Marie a její sestra Marta."],[2,"Byla to ta Marie, která pomazala Pána mastí a utřela mu nohy svými vlasy. Její bratr Lazar byl nemocný."],[3,"Sestry proto poslaly Ježíšovi zprávu: „Pane, ten, kterého máš rád, je nemocný.“"],[4,"Když to Ježíš uslyšel, řekl: „Tato nemoc není k smrti, ale k Boží slávě, aby skrze ni byl oslaven Boží Syn.“"],[5,"Ježíš miloval Martu, její sestru i Lazara."],[6,"Když tedy uslyšel, že je Lazar nemocný, zůstal ještě dva dny na místě, kde byl."],[7,"Potom řekl učedníkům: „Pojďme znovu do Judska.“"],[8,"Učedníci mu řekli: „Mistře, ještě nedávno tě tam Židé chtěli kamenovat, a ty tam chceš jít znovu?“"],[9,"Ježíš odpověděl: „Nemá den dvanáct hodin? Kdo chodí ve dne, nezakopne, protože vidí světlo tohoto světa."],[10,"Kdo však chodí v noci, zakopne, protože v něm není světlo.“"],[11,"Po těchto slovech jim řekl: „Náš přítel Lazar usnul, ale jdu ho probudit.“"],[12,"Učedníci mu odpověděli: „Pane, jestli usnul, uzdraví se.“"],[13,"Ježíš však mluvil o jeho smrti; oni si mysleli, že mluví o obyčejném spánku."],[14,"Proto jim Ježíš řekl otevřeně: „Lazar zemřel."],[15,"Kvůli vám se raduji, že jsem tam nebyl, abyste uvěřili. Pojďme k němu.“"],[16,"Tomáš, zvaný Didymus, řekl ostatním učedníkům: „Pojďme i my, abychom zemřeli s ním.“"]]},{"title":"Ježíš je vzkříšení a život","range":"Jan 11,17–37","thoughts":[],"verses":[[17,"Když Ježíš přišel, zjistil, že Lazar je už čtyři dny v hrobě."],[18,"Betanie byla blízko Jeruzaléma, asi tři kilometry."],[19,"Mnoho Židů přišlo k Martě a Marii, aby je potěšili po smrti jejich bratra."],[20,"Jakmile Marta uslyšela, že Ježíš přichází, vyšla mu naproti. Marie však zůstala doma."],[21,"Marta řekla Ježíšovi: „Pane, kdybys tu byl, můj bratr by nezemřel."],[22,"Ale i teď vím, že cokoli požádáš od Boha, Bůh ti dá.“"],[23,"Ježíš jí řekl: „Tvůj bratr vstane.“"],[24,"Marta odpověděla: „Vím, že vstane při vzkříšení v poslední den.“"],[25,"Ježíš jí řekl: „Já jsem vzkříšení a život. Kdo věří ve mne, bude žít, i kdyby zemřel."],[26,"A každý, kdo žije a věří ve mne, nezemře navěky. Věříš tomu?“"],[27,"Odpověděla mu: „Ano, Pane. Uvěřila jsem, že ty jsi Mesiáš, Boží Syn, který má přijít na svět.“"],[28,"Když to řekla, odešla a tajně zavolala svou sestru Marii: „Mistr je tady a volá tě.“"],[29,"Jakmile to Marie uslyšela, rychle vstala a šla k němu."],[30,"Ježíš ještě nevstoupil do vesnice, ale zůstal na místě, kde se s ním setkala Marta."],[31,"Židé, kteří byli s Marií v domě a utěšovali ji, viděli, že rychle vstala a odešla. Šli za ní, protože si mysleli, že jde k hrobu plakat."],[32,"Když Marie přišla k Ježíšovi a uviděla ho, padla mu k nohám a řekla: „Pane, kdybys tu byl, můj bratr by nezemřel.“"],[33,"Když Ježíš viděl, jak pláče ona i Židé, kteří přišli s ní, hluboce se v duchu pohnul a znepokojil se."],[34,"Zeptal se: „Kam jste ho položili?“ Odpověděli mu: „Pane, pojď se podívat.“"],[35,"Ježíš zaplakal."],[36,"Židé říkali: „Podívejte, jak ho miloval!“"],[37,"Někteří z nich však řekli: „Nemohl ten, který otevřel oči slepému, zařídit, aby Lazar nezemřel?“"]]},{"title":"Vzkříšení Lazara","range":"Jan 11,38–44","thoughts":[],"verses":[[38,"Ježíš, znovu hluboce pohnutý, přišel k hrobu. Byla to jeskyně a její vchod zakrýval kámen."],[39,"Ježíš řekl: „Odvalte kámen.“ Marta, sestra zemřelého, mu řekla: „Pane, už zapáchá. Vždyť je v hrobě čtyři dny.“"],[40,"Ježíš jí odpověděl: „Neřekl jsem ti, že když uvěříš, uvidíš Boží slávu?“"],[41,"Odvalili tedy kámen z místa, kde mrtvý ležel. Ježíš pozvedl oči vzhůru a řekl: „Otče, děkuji ti, že jsi mě vyslyšel."],[42,"Vím, že mě slyšíš vždycky, ale řekl jsem to kvůli zástupu, který stojí kolem, aby uvěřili, že jsi mě poslal.“"],[43,"Po těch slovech hlasitě zavolal: „Lazare, pojď ven!“"],[44,"Mrtvý vyšel ven. Ruce i nohy měl ovázané pruhy plátna a tvář měl ovinutou šátkem. Ježíš jim řekl: „Rozvažte ho a nechte ho odejít.“"]]},{"title":"Rozhodnutí Ježíše zabít","range":"Jan 11,45–57","thoughts":[],"verses":[[45,"Mnozí z Židů, kteří přišli k Marii a viděli, co Ježíš udělal, v něj uvěřili."],[46,"Někteří z nich však odešli k farizeům a řekli jim, co Ježíš udělal."],[47,"Velekněží a farizeové proto svolali radu a říkali: „Co budeme dělat? Tento člověk dělá mnoho znamení."],[48,"Jestliže ho necháme pokračovat, všichni v něj uvěří. Pak přijdou Římané a vezmou nám toto místo i národ.“"],[49,"Jeden z nich, Kaifáš, který byl toho roku veleknězem, jim řekl: „Vy vůbec nic nechápete."],[50,"Neuvědomujete si, že je pro nás lepší, aby jeden člověk zemřel za lid, než aby zahynul celý národ.“"],[51,"To neřekl sám od sebe. Protože byl toho roku veleknězem, prorokoval, že Ježíš má zemřít za národ,"],[52,"a nejen za tento národ, ale také proto, aby shromáždil vjedno rozptýlené Boží děti."],[53,"Od toho dne se tedy radili, jak ho zabít."],[54,"Ježíš proto už veřejně mezi Židy nevystupoval. Odešel odtud do kraje blízko pouště, do města zvaného Efraim, a tam zůstal se svými učedníky."],[55,"Blížily se židovské Velikonoce a mnoho lidí z celého kraje šlo před svátky do Jeruzaléma, aby se obřadně očistili."],[56,"Hledali Ježíše a když stáli v chrámě, říkali si mezi sebou: „Co myslíte? Přijde na svátky?“"],[57,"Velekněží a farizeové totiž vydali příkaz, aby každý, kdo zjistí, kde Ježíš je, oznámil to, aby ho mohli zatknout."]]}];

JOHN_SECTIONS["12"] = [{"title":"Pomazání v Betanii","range":"Jan 12,1–11","thoughts":[],"verses":[[1,"Šest dní před Velikonocemi přišel Ježíš do Betanie, kde žil Lazar, kterého vzkřísil z mrtvých."],[2,"Připravili tam pro něj večeři. Marta obsluhovala a Lazar byl jedním z těch, kdo s Ježíšem seděli u stolu."],[3,"Marie vzala libru velmi drahé masti z pravého nardu, pomazala Ježíšovy nohy a svými vlasy je utřela. Dům se naplnil vůní té masti."],[4,"Jeden z jeho učedníků, Jidáš, syn Šimona Iškariotského, který ho měl zradit, řekl:"],[5,"„Proč se ta mast neprodala za tři sta denárů a peníze se nedaly chudým?“"],[6,"Neřekl to proto, že by mu záleželo na chudých, ale protože byl zloděj. Měl na starosti společný měšec a nosil v něm to, co se do něj dávalo."],[7,"Ježíš řekl: „Nechte ji. Uchovala to ke dni mého pohřbu."],[8,"Chudé máte mezi sebou vždycky, ale mě vždycky mít nebudete.“"],[9,"Velký zástup Židů se dozvěděl, že je Ježíš v Betanii, a přišli nejen kvůli němu, ale také aby viděli Lazara, kterého vzkřísil z mrtvých."],[10,"Velekněží se proto radili, že zabijí i Lazara,"],[11,"protože kvůli němu mnoho Židů odcházelo a věřilo v Ježíše."]]},{"title":"Vjezd do Jeruzaléma","range":"Jan 12,12–19","thoughts":[],"verses":[[12,"Druhého dne se veliký zástup, který přišel na svátky, dozvěděl, že Ježíš přichází do Jeruzaléma."],[13,"Vzali palmové ratolesti, vyšli mu naproti a volali: „Hosanna! Požehnaný, který přichází ve jménu Páně, král Izraele!“"],[14,"Ježíš našel oslátko a posadil se na něj, jak je napsáno:"],[15,"„Neboj se, dcero Siónská. Hle, tvůj král přichází a sedí na oslátku.“"],[16,"Jeho učedníci tomu zpočátku nerozuměli. Když byl však Ježíš oslaven, vzpomněli si, že to o něm bylo napsáno a že právě toto mu lidé udělali."],[17,"Zástup, který byl s Ježíšem, když zavolal Lazara z hrobu a vzkřísil ho z mrtvých, o tom vydával svědectví."],[18,"Proto mu také zástup vyšel naproti, protože lidé slyšeli, že udělal toto znamení."],[19,"Farizeové si mezi sebou říkali: „Vidíte, že nic nezmůžete. Podívejte, celý svět jde za ním!“"]]},{"title":"Řekové chtějí vidět Ježíše","range":"Jan 12,20–36","thoughts":[],"verses":[[20,"Mezi těmi, kdo přicházeli na svátky uctívat Boha, byli také někteří Řekové."],[21,"Ti přišli k Filipovi z galilejské Betsaidy a prosili ho: „Pane, chtěli bychom vidět Ježíše.“"],[22,"Filip to šel říct Ondřejovi a potom to Ondřej s Filipem řekli Ježíšovi."],[23,"Ježíš jim odpověděl: „Přišla hodina, aby byl Syn člověka oslaven."],[24,"Amen, amen, říkám vám: Jestliže pšeničné zrno nepadne do země a nezemře, zůstane samo. Jestliže však zemře, přinese mnoho úrody."],[25,"Kdo miluje svůj život, ztratí ho. Kdo však svůj život v tomto světě nenávidí, uchová ho pro věčný život."],[26,"Kdo mi chce sloužit, ať mě následuje. Kde jsem já, tam bude i můj služebník. Kdo mi slouží, toho Otec poctí."],[27,"Teď je má duše sevřená. Co mám říct? ‚Otče, zachraň mě před touto hodinou‘? Ale právě kvůli této hodině jsem přišel."],[28,"Otče, oslav své jméno!“ Z nebe zazněl hlas: „Oslavil jsem je a znovu je oslavím.“"],[29,"Zástup, který tam stál a slyšel to, říkal, že zahřmělo. Jiní říkali: „Promluvil k němu anděl.“"],[30,"Ježíš odpověděl: „Tento hlas nezazněl kvůli mně, ale kvůli vám."],[31,"Nyní přichází soud nad tímto světem, nyní bude vládce tohoto světa vyvržen ven."],[32,"A já, až budu vyzdvižen ze země, přitáhnu všechny k sobě.“"],[33,"Tím naznačil, jakou smrtí má zemřít."],[34,"Zástup mu odpověděl: „Ze Zákona jsme slyšeli, že Mesiáš zůstává navěky. Jak tedy můžeš říkat, že Syn člověka musí být vyzdvižen? Kdo je ten Syn člověka?“"],[35,"Ježíš jim řekl: „Ještě krátký čas je světlo mezi vámi. Choďte, dokud máte světlo, aby vás nezastihla tma. Kdo chodí ve tmě, neví, kam jde."],[36,"Dokud máte světlo, věřte ve světlo, abyste se stali syny světla.“ Když to Ježíš řekl, odešel a skryl se před nimi."]]},{"title":"Nevíra lidu","range":"Jan 12,37–43","thoughts":[],"verses":[[37,"Ačkoli před nimi udělal tolik znamení, přesto v něj nevěřili."],[38,"Tak se naplnila slova proroka Izajáše: „Pane, kdo uvěřil našemu poselství a komu byla zjevena Hospodinova paže?“"],[39,"Proto nemohli věřit, neboť Izajáš také řekl:"],[40,"„Oslepil jejich oči a zatvrdil jejich srdce, aby očima neviděli, srdcem nepochopili, neobrátili se a já je neuzdravil.“"],[41,"Izajáš to řekl, protože viděl jeho slávu a mluvil o něm."],[42,"Přesto v Ježíše uvěřilo i mnoho předních mužů. Kvůli farizeům se však k němu veřejně nehlásili, aby nebyli vyloučeni ze synagogy."],[43,"Měli totiž raději lidskou slávu než slávu od Boha."]]},{"title":"Ježíšovo poslední veřejné slovo","range":"Jan 12,44–50","thoughts":[],"verses":[[44,"Ježíš zvolal: „Kdo věří ve mne, nevěří jen ve mne, ale v toho, který mě poslal."],[45,"A kdo vidí mě, vidí toho, který mě poslal."],[46,"Přišel jsem na svět jako světlo, aby žádný, kdo ve mě věří, nezůstal ve tmě."],[47,"Jestliže někdo slyší má slova a nevěří jim, já ho nesoudím. Nepřišel jsem totiž, abych svět soudil, ale abych svět zachránil."],[48,"Kdo mě odmítá a nepřijímá má slova, má svého soudce: slovo, které jsem mluvil, ho bude soudit v poslední den."],[49,"Nemluvil jsem totiž sám od sebe. Otec, který mě poslal, mi dal přikázání, co mám říkat a co mám mluvit."],[50,"A vím, že jeho přikázání je věčný život. Proto to, co říkám, říkám tak, jak mi to řekl Otec.“"]]}];

JOHN_SECTIONS["13"] = [{"title":"Ježíš umývá učedníkům nohy","range":"Jan 13,1–20","thoughts":[],"verses":[[1,"Před velikonočními svátky Ježíš věděl, že přišla jeho hodina odejít z tohoto světa k Otci. Miloval své, kteří byli ve světě, a miloval je až do konce."],[2,"Během večeře už ďábel vložil do srdce Jidáše, syna Šimona Iškariotského, aby Ježíše zradil."],[3,"Ježíš věděl, že mu Otec dal všechno do rukou, že vyšel od Boha a k Bohu se vrací."],[4,"Vstal tedy od večeře, odložil svrchní oděv, vzal si zástěru a přepásal se."],[5,"Potom nalil vodu do umyvadla a začal učedníkům umývat nohy a utírat je látkou, kterou měl kolem pasu."],[6,"Když přišel k Šimonu Petrovi, Petr mu řekl: „Pane, ty mi chceš umývat nohy?“"],[7,"Ježíš mu odpověděl: „Teď nerozumíš tomu, co dělám, ale později to pochopíš.“"],[8,"Petr mu řekl: „Nikdy mi nebudeš umývat nohy!“ Ježíš mu odpověděl: „Jestliže tě neumyji, nebudeš mít se mnou podíl.“"],[9,"Šimon Petr mu řekl: „Pane, potom nejen nohy, ale i ruce a hlavu!“"],[10,"Ježíš mu řekl: „Kdo je umytý, potřebuje si umýt už jen nohy, protože je celý čistý. I vy jste čistí, ale ne všichni.“"],[11,"Věděl totiž, kdo ho zradí, a proto řekl: „Ne všichni jste čistí.“"],[12,"Když jim umyl nohy, oblékl si znovu svůj oděv, usedl ke stolu a zeptal se jich: „Chápete, co jsem vám udělal?"],[13,"Nazýváte mě Mistrem a Pánem, a říkáte to správně, protože jím jsem."],[14,"Jestliže jsem vám tedy já, Pán a Mistr, umyl nohy, máte si i vy navzájem umývat nohy."],[15,"Dal jsem vám příklad, abyste i vy jednali tak, jako jsem jednal já s vámi."],[16,"Amen, amen, říkám vám: Služebník není větší než jeho pán ani posel není větší než ten, kdo ho poslal."],[17,"Když to víte, jste blahoslavení, pokud podle toho také jednáte."],[18,"Nemluvím o vás všech. Já vím, které jsem si vyvolil. Musí se však naplnit Písmo: ‚Ten, kdo se mnou jí chléb, pozvedl proti mně patu.‘"],[19,"Říkám vám to už teď, dříve než se to stane, abyste potom, až se to stane, uvěřili, že já jsem."],[20,"Amen, amen, říkám vám: Kdo přijímá toho, koho pošlu, přijímá mě; a kdo přijímá mě, přijímá toho, který mě poslal.“"]]},{"title":"Označení zrádce","range":"Jan 13,21–30","thoughts":[],"verses":[[21,"Po těchto slovech se Ježíš v duchu hluboce znepokojil a prohlásil: „Amen, amen, říkám vám: Jeden z vás mě zradí.“"],[22,"Učedníci se na sebe dívali a nevěděli, o kom mluví."],[23,"Jeden z učedníků, kterého Ježíš miloval, ležel u stolu těsně vedle něj."],[24,"Šimon Petr mu dal znamení, aby se zeptal, koho má Ježíš na mysli."],[25,"Ten se naklonil k Ježíšovi a zeptal se: „Pane, kdo to je?“"],[26,"Ježíš odpověděl: „Je to ten, komu podám omočené sousto.“ Omočil tedy sousto a podal je Jidášovi, synu Šimona Iškariotského."],[27,"Jakmile Jidáš sousto přijal, vstoupil do něj satan. Ježíš mu řekl: „Co chceš udělat, udělej rychle.“"],[28,"Nikdo z těch, kdo byli u stolu, nepochopil, proč mu to Ježíš řekl."],[29,"Protože měl Jidáš na starosti společný měšec, někteří si mysleli, že mu Ježíš řekl, aby nakoupil, co potřebují na svátky, nebo aby něco dal chudým."],[30,"Jidáš tedy přijal sousto a hned odešel. Byla noc."]]},{"title":"Nové přikázání","range":"Jan 13,31–35","thoughts":[],"verses":[[31,"Když Jidáš odešel, Ježíš řekl: „Nyní je Syn člověka oslaven a Bůh je oslaven v něm."],[32,"Jestliže je Bůh oslaven v něm, Bůh ho také oslaví v sobě, a oslaví ho hned."],[33,"Děti, ještě krátký čas jsem s vámi. Budete mě hledat. Jak jsem řekl Židům: ‚Kam jdu já, vy přijít nemůžete,‘ tak to teď říkám i vám."],[34,"Dávám vám nové přikázání: Milujte se navzájem. Jako jsem já miloval vás, tak se i vy milujte navzájem."],[35,"Podle toho všichni poznají, že jste moji učedníci: budete-li mít lásku jedni k druhým.“"]]},{"title":"Ježíš předpovídá Petrovo zapření","range":"Jan 13,36–38","thoughts":[],"verses":[[36,"Šimon Petr se ho zeptal: „Pane, kam jdeš?“ Ježíš odpověděl: „Tam, kam jdu, mě teď následovat nemůžeš, ale později mě budeš následovat.“"],[37,"Petr mu řekl: „Pane, proč tě nemohu následovat už teď? Položím za tebe svůj život!“"],[38,"Ježíš mu odpověděl: „Položíš za mě svůj život? Amen, amen, říkám ti: Kohout nezakokrhá, dokud mě třikrát nezapřeš.“"]]}];

JOHN_SECTIONS["14"] = [{"title":"Ježíš je cesta, pravda a život","range":"Jan 14,1–14","thoughts":[],"verses":[[1,"„Ať se vaše srdce netrápí. Věřte v Boha a věřte i ve mne."],[2,"V domě mého Otce je mnoho příbytků. Kdyby tomu tak nebylo, řekl bych vám to. Jdu vám připravit místo."],[3,"Až odejdu a připravím vám místo, znovu přijdu a vezmu vás k sobě, abyste i vy byli tam, kde jsem já."],[4,"Víte, kam jdu, a znáte cestu.“"],[5,"Tomáš mu řekl: „Pane, nevíme, kam jdeš. Jak tedy můžeme znát cestu?“"],[6,"Ježíš mu odpověděl: „Já jsem cesta, pravda i život. Nikdo nepřichází k Otci než skrze mne."],[7,"Kdybyste znali mě, znali byste i mého Otce. Od nynějška ho znáte a viděli jste ho.“"],[8,"Filip mu řekl: „Pane, ukaž nám Otce a to nám stačí.“"],[9,"Ježíš mu odpověděl: „Tak dlouho jsem s vámi, Filipe, a ještě mě neznáš? Kdo viděl mě, viděl Otce. Jak tedy můžeš říkat: ‚Ukaž nám Otce‘?"],[10,"Nevěříš, že já jsem v Otci a Otec je ve mně? Slova, která vám říkám, nemluvím sám od sebe. Otec, který ve mně přebývá, koná své skutky."],[11,"Věřte mi, že já jsem v Otci a Otec ve mně. A pokud ne pro má slova, věřte alespoň kvůli těm skutkům."],[12,"Amen, amen, říkám vám: Kdo ve mě věří, bude dělat skutky, které dělám já, a bude dělat ještě větší, protože já jdu ke svému Otci."],[13,"A o cokoli budete prosit v mém jménu, to udělám, aby byl Otec oslaven v Synu."],[14,"Budete-li o něco prosit v mém jménu, udělám to."]]},{"title":"Příslib Ducha svatého","range":"Jan 14,15–26","thoughts":[],"verses":[[15,"Jestliže mě milujete, zachovávejte má přikázání."],[16,"Já požádám Otce a on vám dá jiného Utěšitele, aby s vámi zůstal navěky:"],[17,"Ducha pravdy, kterého svět nemůže přijmout, protože ho nevidí ani nezná. Vy ho však znáte, protože přebývá u vás a bude ve vás."],[18,"Nenechám vás jako sirotky. Přijdu k vám."],[19,"Ještě krátký čas a svět mě už neuvidí, ale vy mě uvidíte. Protože já žiji, budete žít i vy."],[20,"V ten den poznáte, že já jsem ve svém Otci, vy ve mně a já ve vás."],[21,"Kdo má má přikázání a zachovává je, ten mě miluje. Kdo mě miluje, toho bude milovat můj Otec; i já ho budu milovat a zjevím mu sám sebe.“"],[22,"Juda, ne ten Iškariotský, se ho zeptal: „Pane, jak to, že se chceš zjevit nám, a ne světu?“"],[23,"Ježíš mu odpověděl: „Kdo mě miluje, bude zachovávat mé slovo. Můj Otec ho bude milovat, přijdeme k němu a budeme u něj přebývat."],[24,"Kdo mě nemiluje, má slova nezachovává. Slovo, které slyšíte, není moje, ale Otcovo, který mě poslal."],[25,"To jsem vám říkal, dokud jsem ještě s vámi."],[26,"Utěšitel, Duch svatý, kterého Otec pošle v mém jménu, vás naučí všemu a připomene vám všechno, co jsem vám řekl."]]},{"title":"Ježíš dává svůj pokoj","range":"Jan 14,27–31","thoughts":[],"verses":[[27,"Pokoj vám zanechávám, svůj pokoj vám dávám. Nedávám vám ho tak, jak ho dává svět. Ať se vaše srdce netrápí ani nebojí."],[28,"Slyšeli jste, že jsem vám řekl: ‚Odcházím a znovu k vám přijdu.‘ Kdybyste mě milovali, radovali byste se, že jdu k Otci, protože Otec je větší než já."],[29,"Řekl jsem vám to už teď, dříve než se to stane, abyste uvěřili, až se to stane."],[30,"Už s vámi nebudu mnoho mluvit, protože přichází vládce tohoto světa. Nade mnou však nemá žádnou moc."],[31,"Ale svět má poznat, že miluji Otce a že jednám právě tak, jak mi Otec přikázal. Vstaňte, pojďme odtud.“"]]}];

JOHN_SECTIONS["15"] = [{"title":"Pravý vinný kmen","range":"Jan 15,1–17","thoughts":[],"verses":[[1,"„Já jsem pravý vinný kmen a můj Otec je vinař."],[2,"Každou ratolest ve mně, která nenese ovoce, odřezává, a každou, která ovoce nese, čistí, aby nesla ještě více ovoce."],[3,"Vy už jste čistí díky slovu, které jsem vám řekl."],[4,"Zůstaňte ve mně a já ve vás. Jako ratolest nemůže nést ovoce sama od sebe, pokud nezůstane na vinném kmeni, tak ani vy, pokud nezůstanete ve mně."],[5,"Já jsem vinný kmen a vy jste ratolesti. Kdo zůstává ve mně a já v něm, ten nese mnoho ovoce, protože beze mne nemůžete udělat nic."],[6,"Kdo ve mně nezůstane, bude vyhozen ven jako ratolest a uschne. Takové ratolesti se pak sesbírají, hodí do ohně a shoří."],[7,"Jestliže zůstanete ve mně a má slova zůstanou ve vás, proste o cokoli chcete a stane se vám."],[8,"Tím je oslaven můj Otec: když nesete mnoho ovoce a jste mými učedníky."],[9,"Jako Otec miloval mě, tak jsem i já miloval vás. Zůstaňte v mé lásce."],[10,"Budete-li zachovávat má přikázání, zůstanete v mé lásce, tak jako jsem já zachovával přikázání svého Otce a zůstávám v jeho lásce."],[11,"To jsem vám řekl, aby má radost byla ve vás a aby vaše radost byla úplná."],[12,"Toto je mé přikázání: Milujte se navzájem, jako jsem já miloval vás."],[13,"Nikdo nemá větší lásku než ten, kdo položí svůj život za své přátele."],[14,"Vy jste moji přátelé, jestliže děláte to, co vám přikazuji."],[15,"Už vás nenazývám služebníky, protože služebník neví, co dělá jeho pán. Nazval jsem vás přáteli, protože jsem vám oznámil všechno, co jsem slyšel od svého Otce."],[16,"Ne vy jste si vyvolili mě, ale já jsem vyvolil vás a určil jsem vás k tomu, abyste šli, nesli ovoce a vaše ovoce zůstalo. Potom vám Otec dá cokoli, oč ho budete prosit v mém jménu."],[17,"Toto vám přikazuji: Milujte se navzájem."]]},{"title":"Nenávist světa","range":"Jan 15,18–27","thoughts":[],"verses":[[18,"Jestliže vás svět nenávidí, vězte, že mě nenáviděl dříve než vás."],[19,"Kdybyste patřili světu, svět by miloval to, co je jeho. Vy však ze světa nejste, protože jsem si vás ze světa vyvolil. Proto vás svět nenávidí."],[20,"Pamatujte na slova, která jsem vám řekl: ‚Služebník není větší než jeho pán.‘ Jestliže pronásledovali mě, budou pronásledovat i vás. Jestliže zachovávali mé slovo, budou zachovávat i vaše."],[21,"To všechno vám budou dělat kvůli mému jménu, protože neznají toho, který mě poslal."],[22,"Kdybych nepřišel a nemluvil k nim, neměli by hřích. Teď však pro svůj hřích nemají výmluvu."],[23,"Kdo nenávidí mě, nenávidí i mého Otce."],[24,"Kdybych mezi nimi nedělal skutky, které nikdo jiný neudělal, neměli by hřích. Teď je však viděli, a přesto nenáviděli mě i mého Otce."],[25,"Tak se naplnilo slovo napsané v jejich Zákoně: ‚Nenáviděli mě bez příčiny.‘"],[26,"Až přijde Utěšitel, kterého vám pošlu od Otce, Duch pravdy, který pochází od Otce, ten o mně bude vydávat svědectví."],[27,"A také vy budete svědčit, protože jste se mnou od začátku."]]}];

JOHN_SECTIONS["16"] = [{"title":"Pronásledování učedníků","range":"Jan 16,1–4","thoughts":[],"verses":[[1,"„To jsem vám řekl, abyste nezakolísali."],[2,"Budou vás vylučovat ze synagog. Přijde dokonce hodina, kdy si každý, kdo vás zabije, bude myslet, že tím slouží Bohu."],[3,"Budou to dělat proto, že nepoznali Otce ani mě."],[4,"Řekl jsem vám to, abyste si, až ten čas přijde, vzpomněli, že jsem vás na to předem upozornil. Od začátku jsem vám to neříkal, protože jsem byl s vámi."]]},{"title":"Působení Ducha svatého","range":"Jan 16,5–15","thoughts":[],"verses":[[5,"Teď však odcházím k tomu, který mě poslal, a nikdo z vás se mě neptá: ‚Kam jdeš?‘"],[6,"Protože jsem vám to řekl, naplnil vaše srdce zármutek."],[7,"Říkám vám však pravdu: je pro vás dobré, abych odešel. Když neodejdu, Utěšitel k vám nepřijde. Když však odejdu, pošlu ho k vám."],[8,"Až přijde, ukáže světu, v čem je hřích, spravedlnost a soud:"],[9,"hřích v tom, že ve mě nevěří;"],[10,"spravedlnost v tom, že odcházím k Otci a už mě neuvidíte;"],[11,"a soud v tom, že vládce tohoto světa je už odsouzen."],[12,"Ještě vám mám mnoho co říct, ale teď byste to neunesli."],[13,"Až však přijde Duch pravdy, uvede vás do celé pravdy. Nebude totiž mluvit sám od sebe, ale bude mluvit to, co uslyší, a oznámí vám i to, co má přijít."],[14,"On mě oslaví, protože vezme z toho, co je moje, a oznámí vám to."],[15,"Všechno, co má Otec, je moje. Proto jsem řekl, že vezme z toho, co je moje, a oznámí vám to."]]},{"title":"Smutek se promění v radost","range":"Jan 16,16–24","thoughts":[],"verses":[[16,"„Ještě chvíli a neuvidíte mě; a zase chvíli a uvidíte mě, protože jdu k Otci.“"],[17,"Někteří z jeho učedníků si mezi sebou říkali: „Co znamená to, co nám říká: ‚Ještě chvíli a neuvidíte mě; a zase chvíli a uvidíte mě‘ a ‚Jdu k Otci‘?“"],[18,"Ptali se tedy: „Co znamená to jeho ‚ještě chvíli‘? Nevíme, o čem mluví.“"],[19,"Ježíš poznal, že se ho na to chtějí zeptat, a řekl jim: „Ptáte se mezi sebou na to, že jsem řekl: ‚Ještě chvíli a neuvidíte mě; a zase chvíli a uvidíte mě‘?"],[20,"Amen, amen, říkám vám: Vy budete plakat a naříkat, ale svět se bude radovat. Vy budete zarmouceni, ale váš zármutek se promění v radost."],[21,"Když žena rodí, prožívá bolest, protože přišla její hodina. Když však porodí dítě, už si na svou bolest nevzpomíná pro radost, že se na svět narodil člověk."],[22,"Tak i vy máte teď zármutek, ale znovu vás uvidím a vaše srdce se zaraduje. A vaši radost vám nikdo nevezme."],[23,"V ten den se mě už nebudete na nic ptát. Amen, amen, říkám vám: O cokoli požádáte Otce v mém jménu, dá vám to."],[24,"Dosud jste o nic neprosili v mém jménu. Proste a dostanete, aby vaše radost byla úplná."]]},{"title":"Ježíš zvítězil nad světem","range":"Jan 16,25–33","thoughts":[],"verses":[[25,"„To jsem vám říkal v obrazech. Přichází však hodina, kdy už k vám nebudu mluvit v obrazech, ale otevřeně vám budu vyprávět o Otci."],[26,"V ten den budete prosit v mém jménu. Neříkám vám, že budu prosit Otce za vás,"],[27,"protože sám Otec vás miluje, neboť jste si zamilovali mě a uvěřili jste, že jsem vyšel od Boha."],[28,"Vyšel jsem od Otce a přišel jsem na svět. Teď svět zase opouštím a jdu k Otci.“"],[29,"Jeho učedníci mu řekli: „Teď už mluvíš otevřeně a nepoužíváš žádná podobenství."],[30,"Teď víme, že víš všechno a nepotřebuješ, aby se tě někdo ptal. Proto věříme, že jsi vyšel od Boha.“"],[31,"Ježíš jim odpověděl: „Teď věříte?"],[32,"Hle, přichází hodina, a už přišla, kdy se rozprchnete každý ke svému a mě necháte samotného. Ale nejsem sám, protože Otec je se mnou."],[33,"To jsem vám řekl, abyste ve mně měli pokoj. Ve světě budete mít soužení. Ale buďte dobré mysli: já jsem přemohl svět.“"]]}];

JOHN_SECTIONS["17"] = [{"title":"Ježíš se modlí za sebe","range":"Jan 17,1–5","thoughts":[],"verses":[[1,"Když to Ježíš řekl, pozvedl oči k nebi a modlil se: „Otče, přišla hodina. Oslav svého Syna, aby i Syn oslavil tebe."],[2,"Dal jsi mu moc nad každým člověkem, aby všem, které jsi mu dal, dal věčný život."],[3,"A věčný život je v tom, aby poznali tebe, jediného pravého Boha, a Ježíše Krista, kterého jsi poslal."],[4,"Já jsem tě oslavil na zemi a dokončil jsem dílo, které jsi mi dal vykonat."],[5,"A teď mě ty, Otče, oslav u sebe slávou, kterou jsem u tebe měl dříve, než byl svět."]]},{"title":"Ježíš se modlí za učedníky","range":"Jan 17,6–19","thoughts":[],"verses":[[6,"„Zjevil jsem tvé jméno lidem, které jsi mi dal ze světa. Byli tvoji, dal jsi je mně a oni zachovali tvé slovo."],[7,"Teď poznali, že všechno, co jsi mi dal, pochází od tebe."],[8,"Slova, která jsi mi dal, jsem dal jim. Oni je přijali a skutečně poznali, že jsem vyšel od tebe, a uvěřili, že jsi mě poslal."],[9,"Za ně prosím. Neprosím za svět, ale za ty, které jsi mi dal, protože jsou tvoji."],[10,"Všechno moje je tvoje a všechno tvoje je moje. A v nich jsem oslaven."],[11,"Já už nejsem ve světě, ale oni ve světě zůstávají a já jdu k tobě. Svatý Otče, zachovej je ve svém jménu, které jsi mi dal, aby byli jedno jako my."],[12,"Dokud jsem byl s nimi ve světě, chránil jsem je ve tvém jménu. Ty, které jsi mi dal, jsem zachoval a žádný z nich nezahynul kromě syna zatracení, aby se naplnilo Písmo."],[13,"Teď však jdu k tobě a toto říkám ještě ve světě, aby měli v sobě plnost mé radosti."],[14,"Dal jsem jim tvé slovo a svět je nenáviděl, protože nejsou ze světa, stejně jako já nejsem ze světa."],[15,"Neprosím, abys je vzal ze světa, ale abys je zachoval od zlého."],[16,"Nejsou ze světa, stejně jako já nejsem ze světa."],[17,"Posvěť je v pravdě; tvé slovo je pravda."],[18,"Jako jsi ty poslal mě na svět, tak jsem i já poslal je na svět."],[19,"A za ně posvěcuji sám sebe, aby i oni byli posvěceni v pravdě."]]},{"title":"Ježíš se modlí za všechny věřící","range":"Jan 17,20–26","thoughts":[],"verses":[[20,"„Neprosím však jen za ně, ale i za ty, kteří skrze jejich slovo uvěří ve mě,"],[21,"aby všichni byli jedno. Jako ty, Otče, jsi ve mně a já v tobě, ať jsou i oni jedno v nás, aby svět uvěřil, že jsi mě poslal."],[22,"Slávu, kterou jsi dal mně, jsem dal jim, aby byli jedno, jako jsme my jedno:"],[23,"já v nich a ty ve mně, aby dospěli k dokonalé jednotě a aby svět poznal, že jsi mě poslal a že jsi je miloval, jako jsi miloval mě."],[24,"Otče, chci, aby ti, které jsi mi dal, byli se mnou tam, kde jsem já, aby viděli mou slávu, kterou jsi mi dal, protože jsi mě miloval před založením světa."],[25,"Spravedlivý Otče, svět tě nepoznal, ale já tě znám a tito poznali, že jsi mě poslal."],[26,"Dal jsem jim poznat tvé jméno a budu je dávat poznávat dál, aby láska, kterou jsi miloval mě, byla v nich a já abych byl v nich.“"]]}];

JOHN_SECTIONS["18"] = [{"title":"Ježíšovo zatčení","range":"Jan 18,1–11","thoughts":[],"verses":[[1,"Když Ježíš domluvil, odešel se svými učedníky za potok Cedron. Byla tam zahrada, do které vstoupil on i jeho učedníci."],[2,"To místo znal i Jidáš, který ho zradil, protože se tam Ježíš se svými učedníky často scházel."],[3,"Jidáš tedy vzal oddíl vojáků a stráž od velekněží a farizeů a přišel tam s lucernami, pochodněmi a zbraněmi."],[4,"Ježíš věděl všechno, co ho má potkat. Vyšel jim naproti a zeptal se: „Koho hledáte?“"],[5,"Odpověděli mu: „Ježíše Nazaretského.“ Ježíš řekl: „Já jsem.“ Stál tam s nimi i Jidáš, jeho zrádce."],[6,"Když jim řekl: „Já jsem,“ ustoupili dozadu a padli na zem."],[7,"Zeptal se jich znovu: „Koho hledáte?“ Odpověděli: „Ježíše Nazaretského.“"],[8,"Ježíš řekl: „Už jsem vám řekl, že já jsem. Jestliže tedy hledáte mě, nechte tyto odejít.“"],[9,"Tak se naplnila slova, která řekl: „Z těch, které jsi mi dal, jsem neztratil nikoho.“"],[10,"Šimon Petr měl meč. Vytáhl ho, udeřil služebníka velekněze a uťal mu pravé ucho. Ten služebník se jmenoval Malchus."],[11,"Ježíš řekl Petrovi: „Schovej meč do pochvy. Což nemám vypít kalich, který mi dal Otec?“"]]},{"title":"Ježíš před Annášem a Kaifášem","range":"Jan 18,12–24","thoughts":[],"verses":[[12,"Vojáci, jejich velitel a židovská stráž Ježíše zatkli a svázali."],[13,"Nejprve ho odvedli k Annášovi. Ten byl tchánem Kaifáše, který byl toho roku veleknězem."],[14,"Kaifáš byl ten, který Židům poradil, že je lepší, aby jeden člověk zemřel za lid."],[15,"Za Ježíšem šel Šimon Petr a ještě jiný učedník. Ten byl známý veleknězi, a proto vešel s Ježíšem na nádvoří veleknězova domu."],[16,"Petr však zůstal venku u dveří. Druhý učedník, který byl veleknězi známý, vyšel, promluvil s vrátnou a přivedl Petra dovnitř."],[17,"Služka u dveří se Petra zeptala: „Nejsi i ty jedním z učedníků toho člověka?“ Odpověděl: „Nejsem.“"],[18,"Služebníci a strážci rozdělali oheň, protože byla zima, a ohřívali se. Petr stál mezi nimi a také se ohříval."],[19,"Velekněz se Ježíše vyptával na jeho učedníky a na jeho učení."],[20,"Ježíš mu odpověděl: „Mluvil jsem ke světu veřejně. Vždycky jsem učil v synagogách a v chrámě, kde se Židé scházejí. Nic jsem nemluvil tajně."],[21,"Proč se ptáš mě? Zeptej se těch, kteří slyšeli, co jsem jim říkal. Ti vědí, co jsem mluvil.“"],[22,"Když to Ježíš řekl, jeden ze strážců, který stál poblíž, ho udeřil a řekl: „Takto odpovídáš veleknězi?“"],[23,"Ježíš mu odpověděl: „Jestliže jsem řekl něco špatného, dosvědč, co bylo špatně. Jestliže jsem mluvil správně, proč mě biješ?“"],[24,"Annáš ho pak poslal svázaného k veleknězi Kaifášovi."]]},{"title":"Petr zapírá Ježíše","range":"Jan 18,25–27","thoughts":[],"verses":[[25,"Šimon Petr stále stál a ohříval se. Zeptali se ho: „Nejsi i ty jedním z jeho učedníků?“ On to zapřel a řekl: „Nejsem.“"],[26,"Jeden ze služebníků velekněze, příbuzný toho, kterému Petr uťal ucho, se zeptal: „Copak jsem tě s ním neviděl v zahradě?“"],[27,"Petr to znovu zapřel. A vtom zakokrhal kohout."]]},{"title":"Ježíš před Pilátem","range":"Jan 18,28–40","thoughts":[],"verses":[[28,"Od Kaifáše odvedli Ježíše do místodržitelského paláce. Bylo časně ráno. Sami dovnitř nevstoupili, aby se neposkvrnili a mohli jíst velikonočního beránka."],[29,"Pilát tedy vyšel k nim a zeptal se: „Jakou žalobu vznášíte proti tomuto člověku?“"],[30,"Odpověděli mu: „Kdyby to nebyl zločinec, nevydali bychom ti ho.“"],[31,"Pilát jim řekl: „Vezměte si ho a suďte ho podle svého Zákona.“ Židé mu odpověděli: „My nemáme právo nikoho popravit.“"],[32,"Tak se naplnila Ježíšova slova, kterými naznačil, jakou smrtí má zemřít."],[33,"Pilát se vrátil do paláce, zavolal si Ježíše a zeptal se ho: „Ty jsi židovský král?“"],[34,"Ježíš odpověděl: „Říkáš to sám od sebe, nebo ti to o mně řekli jiní?“"],[35,"Pilát odpověděl: „Copak jsem Žid? Tvůj vlastní národ a velekněží mi tě vydali. Co jsi udělal?“"],[36,"Ježíš odpověděl: „Mé království není z tohoto světa. Kdyby mé království bylo z tohoto světa, moji služebníci by bojovali, abych nebyl vydán Židům. Mé království však není odsud.“"],[37,"Pilát mu řekl: „Takže jsi král?“ Ježíš odpověděl: „Ty říkáš, že jsem král. Já jsem se proto narodil a proto jsem přišel na svět, abych vydal svědectví pravdě. Každý, kdo je z pravdy, slyší můj hlas.“"],[38,"Pilát se ho zeptal: „Co je pravda?“ Potom znovu vyšel k Židům a řekl jim: „Já na něm žádnou vinu nenalézám."],[39,"Je však vaším zvykem, že vám o Velikonocích jednoho vězně propouštím. Chcete tedy, abych vám propustil židovského krále?“"],[40,"Oni znovu vykřikli: „Ne jeho, ale Barabáše!“ Barabáš byl zločinec."]]}];

JOHN_SECTIONS["19"] = [{"title":"Ježíš odsouzen k ukřižování","range":"Jan 19,1–16","thoughts":[],"verses":[[1,"Pilát tedy vzal Ježíše a nechal ho zbičovat."],[2,"Vojáci upletli z trní korunu, nasadili mu ji na hlavu a oblékli ho do purpurového pláště."],[3,"Přicházeli k němu a říkali: „Buď zdráv, židovský králi!“ A bili ho."],[4,"Pilát znovu vyšel ven a řekl jim: „Podívejte, přivádím vám ho ven, abyste věděli, že na něm nenalézám žádnou vinu.“"],[5,"Ježíš vyšel ven s trnovou korunou a purpurovým pláštěm. Pilát jim řekl: „Hle, člověk!“"],[6,"Když ho velekněží a strážci uviděli, začali křičet: „Ukřižuj! Ukřižuj ho!“ Pilát jim řekl: „Vezměte si ho a ukřižujte ho vy. Já na něm žádnou vinu nenalézám.“"],[7,"Židé mu odpověděli: „My máme Zákon a podle našeho Zákona musí zemřít, protože se vydával za Božího Syna.“"],[8,"Když Pilát uslyšel tato slova, dostal ještě větší strach."],[9,"Znovu vešel do paláce a zeptal se Ježíše: „Odkud jsi?“ Ježíš mu však neodpověděl."],[10,"Pilát mu řekl: „Se mnou nemluvíš? Nevíš, že mám moc tě ukřižovat a mám moc tě propustit?“"],[11,"Ježíš odpověděl: „Neměl bys nade mnou žádnou moc, kdyby ti nebyla dána shůry. Proto má větší hřích ten, kdo mě tobě vydal.“"],[12,"Od té chvíle se Pilát snažil Ježíše propustit. Židé však křičeli: „Jestliže ho propustíš, nejsi přítel císaře. Každý, kdo se dělá králem, staví se proti císaři.“"],[13,"Když Pilát uslyšel tato slova, vyvedl Ježíše ven a posadil se na soudcovskou stolici na místě zvaném Kamenná dlažba, hebrejsky Gabbata."],[14,"Byl den přípravy před Velikonocemi, kolem poledne. Pilát řekl Židům: „Hle, váš král!“"],[15,"Oni však křičeli: „Pryč s ním! Pryč s ním! Ukřižuj ho!“ Pilát se jich zeptal: „Mám ukřižovat vašeho krále?“ Velekněží odpověděli: „Nemáme krále kromě císaře.“"],[16,"Tehdy jim Ježíše vydal, aby byl ukřižován. Vzali ho tedy a odvedli."]]},{"title":"Ukřižování","range":"Jan 19,17–27","thoughts":[],"verses":[[17,"Ježíš nesl svůj kříž a vyšel na místo zvané Lebka, hebrejsky Golgota."],[18,"Tam ho ukřižovali a s ním ještě dva jiné, jednoho po každé straně a Ježíše uprostřed."],[19,"Pilát nechal napsat nápis a připevnit ho na kříž. Stálo na něm: „Ježíš Nazaretský, král Židů.“"],[20,"Tento nápis četlo mnoho Židů, protože místo, kde byl Ježíš ukřižován, bylo blízko města. Nápis byl napsán hebrejsky, řecky a latinsky."],[21,"Židovští velekněží proto Pilátovi říkali: „Nepiš: ‚Král Židů,‘ ale: ‚On řekl: Jsem král Židů.‘“"],[22,"Pilát odpověděl: „Co jsem napsal, napsal jsem.“"],[23,"Když vojáci Ježíše ukřižovali, vzali jeho šaty a rozdělili je na čtyři díly, každému vojákovi jeden. Vzali také jeho tuniku. Ta byla beze švu, celá utkaná odshora dolů."],[24,"Řekli si tedy: „Netrhejme ji, ale losujme o ni, komu připadne.“ Tak se naplnilo Písmo: „Rozdělili si mé šaty a o můj oděv losovali.“ A právě to vojáci udělali."],[25,"U Ježíšova kříže stála jeho matka, sestra jeho matky, Marie Kleofášova a Marie Magdaléna."],[26,"Když Ježíš uviděl svou matku a vedle ní učedníka, kterého miloval, řekl matce: „Ženo, hle, tvůj syn.“"],[27,"Potom řekl učedníkovi: „Hle, tvá matka.“ Od té chvíle si ji ten učedník vzal k sobě."]]},{"title":"Ježíšova smrt","range":"Jan 19,28–37","thoughts":[],"verses":[[28,"Ježíš věděl, že už je všechno dokonáno. Aby se naplnilo Písmo, řekl: „Žízním.“"],[29,"Stála tam nádoba plná octa. Namočili tedy houbu do octa, nasadili ji na yzop a podali mu ji k ústům."],[30,"Když Ježíš okusil ocet, řekl: „Dokonáno je.“ Potom sklonil hlavu a odevzdal ducha."],[31,"Protože byl den přípravy a těla neměla zůstat na kříži přes sobotu — ta sobota byla totiž velikým svátkem — požádali Židé Piláta, aby ukřižovaným byly zlámány nohy a jejich těla byla sňata."],[32,"Vojáci tedy přišli a zlámali nohy prvnímu i druhému, kteří byli ukřižováni s Ježíšem."],[33,"Když však přišli k Ježíšovi a viděli, že je už mrtvý, nohy mu nezlámali."],[34,"Jeden z vojáků mu však probodl bok kopím a hned vyšla krev a voda."],[35,"Ten, který to viděl, o tom vydal svědectví a jeho svědectví je pravdivé. Ví, že říká pravdu, abyste i vy uvěřili."],[36,"Stalo se to, aby se naplnilo Písmo: „Ani kost mu nebude zlomena.“"],[37,"A jiné místo Písma říká: „Pohlédnou na toho, kterého probodli.“"]]},{"title":"Ježíšův pohřeb","range":"Jan 19,38–42","thoughts":[],"verses":[[38,"Potom Josef z Arimatie, který byl Ježíšovým učedníkem, ale ze strachu před Židy tajným, požádal Piláta, aby mohl sejmout Ježíšovo tělo. Pilát mu to dovolil. Josef tedy přišel a tělo sňal."],[39,"Přišel také Nikodém, který kdysi navštívil Ježíše v noci. Přinesl směs myrhy a aloe, asi sto liber."],[40,"Vzali Ježíšovo tělo a zavinuli je do pláten spolu s vonnými látkami, jak je u Židů zvykem při pohřbívání."],[41,"Na místě, kde byl Ježíš ukřižován, byla zahrada a v té zahradě nový hrob, do kterého ještě nikdo nebyl uložen."],[42,"Protože byl židovský den přípravy a hrob byl blízko, uložili Ježíše tam."]]}];

JOHN_SECTIONS["20"] = [{"title":"Prázdný hrob","range":"Jan 20,1–10","thoughts":[],"verses":[[1,"Prvního pak dne po sobotě Maria Magdaléna šla ráno k hrobu, když ještě tma bylo. A uzřela kámen odvalený od hrobu."],[2,"běžela a přišla k Šimonovi Petrovi a k druhému učedníkovi, tomu, jehož miloval Ježíš, a řekla jim: Vzali Pána z hrobu, a nevíme, kde ho položili."],[3,"vyšel Petr i ten druhý učedník, a šli k hrobu."],[4,"Běželi pak oba spolu. Ale ten druhý učedník předběhl Petra, a přišel prvé k hrobu."],[5,"nachýliv se, uviděl prostěradla položená, ale však tam nevšel."],[6,"přišel Šimon Petr, za ním jda, a všel do hrobu. A uviděl prostěradla položená,"],[7,"rouchu, kteráž byla na hlavě jeho, ne s prostěradly položenou, ale obzvláštně svinutou na jednom místě."],[8,"všel i ten druhý učedník, kterýž byl prvé přišel k hrobu, i uviděl a uvěřil."],[9,"Protože ještě neznali písma, že měl z mrtvých vstáti."],[10,"odešli zase ti učedlníci tam, kdež prvé byli."]]},{"title":"Ježíš se ukazuje Marii Magdaléně","range":"Jan 20,11–18","thoughts":[],"verses":[[11,"Ale Maria stála u hrobu vně, plačeci. A když plakala, naklonila se do hrobu."],[12,"uzřela dva anděly v bílém rouše sedící, jednoho u hlavy, a druhého u noh, tu kdež bylo položeno tělo Ježíšovo."],[13,"Kteříž řekli jí: Ženo, co pláčeš? A dí jim: Vzali Pána mého, a nevím, kde ho položili."],[14,"To když řekla, obrátila se zpátkem, a uzřela Ježíše, an stojí, ale nevěděla, by Ježíš byl."],[15,"Dí jí Ježíš: Ženo, co pláčeš? Koho hledáš? Ona domnívajici se, že by zahradník byl, řekla mu? Pane, vzal-lis ty ho, pověz mi, kdes ho položil, ať já ho vezmu."],[16,"Řekl jí Ježíš: Maria. Obrátivši se ona, řekla mu: Rabbóni, což se vykládá: Mistře."],[17,"Dí jí Ježíš: Nedotýkejž se mne; nebo jsem ještě nevstoupil k Otci svému. Ale jdiž k bratřím mým, a pověz jim: Vstupuji k Otci svému, a k Otci vašemu, k Bohu svému, a k Bohu vašemu."],[18,"Přišla Maria Magdaléna, zvěstujici učedníkům, že by viděla Pána, a že jí to pověděl."]]},{"title":"Ježíš se ukazuje učedníkům","range":"Jan 20,19–23","thoughts":[],"verses":[[19,"Když pak byl večer toho dne, kterýž je první po sobotě, a dvéře byly zavříny, kdež byli učedlníci shromážděni, pro strach Židovský, přišel Ježíš, a stál u prostřed, a řekl jim: Pokoj vám."],[20,"to pověděv, ukázal jim ruce i bok svůj. A zradovali se učedlníci, vidouce Pána."],[21,"řekl jim Ježíš znovu: Pokoj vám. Jakož mne poslal Otec, tak i já posílám vás."],[22,"to pověděv, dechl, a řekl jim: Přijměte Ducha svatého."],[23,"Kterýmžkoli odpustili byste hříchy, odpouštějíť se jim; kterýmžkoli zadrželi byste, zadržániť jsou."]]},{"title":"Tomáš uvěří","range":"Jan 20,24–29","thoughts":[],"verses":[[24,"Tomáš pak jeden ze dvanácti, kterýž sloul Didymus, nebyl s nimi, když byl přišel Ježíš."],[25,"řekli mu jiní učedlníci: Viděli jsme Pána. Ale on řekl jim: Leč uzřím v rukou jeho bodení hřebů, a vpustím prst svůj v místo hřebů, a ruku svou vložím v bok jeho, nikoli neuvěřím."],[26,"po osmi dnech znovu učedlníci jeho byli vnitř, a Tomáš s nimi. Přišel Ježíš, a dvéře byly zavříny, i stál u prostřed a řekl: Pokoj vám."],[27,"řekl Tomášovi: Vložiž prst svůj sem, a viz ruce mé, a vztáhni ruku svou, a vpusť v bok můj, a nebudiž nevěřící, ale věrný."],[28,"odpověděl Tomáš a řekl mu: Pán můj a Bůh můj!"],[29,"Dí mu Ježíš: Žes mne viděl, Tomáši, uvěřil jsi. Blahoslavení, kteříž neviděli, a uvěřili."]]},{"title":"Účel evangelia","range":"Jan 20,30–31","thoughts":[],"verses":[[30,"Mnohé zajisté i jiné divy činil Ježíš před oblíčejem učedníků svých, kteříž nejsou zapsáni v knize této."],[31,"Ale tito zapsáni jsou, abyste věřili, že Ježíš je Kristus, Syn Boží, a abyste věříce, život měli ve jménu jeho."]]}];

JOHN_SECTIONS["21"] = [{"title":"Ježíš se ukazuje u Tiberiadského moře","range":"Jan 21,1–14","thoughts":[],"verses":[[1,"zjevil se znovu Ježíš učedníkům u moře Tiberiadského. Zjevil se pak takto:"],[2,"Byli spolu Šimon Petr a Tomáš, kterýž sloul Didymus, a Natanael, kterýž byl z Kány Galilejské, a synové Zebedeovi, a jiní z učedníků jeho dva."],[3,"Dí jim Šimon Petr: Půjdu ryb loviti. Řekli mu: Půjdeme i my s tebou. A šli, a vstoupili na lodí hned; a té noci nic nepopadli."],[4,"když bylo již ráno, stál Ježíš na břehu. Nevěděli však učedlníci, by Ježíš byl."],[5,"dí jim Ježíš: Dítky, máte-li jakou krmičku? Odpověděli mu: Nemáme."],[6,"On pak řekl jim: Zavrztež sít na pravou stranu lodí, a naleznete. A zavrhli, a hned nemohli ji táhnouti pro množství ryb."],[7,"řekl učedník ten, kteréhož miloval Ježíš, Petrovi: Pán je. A Šimon Petr, jakž uslyšel, že Pán je, opásal se po košili, (nebo byl nah), a pustil se do moře."],[8,"Jiní také učedlníci na lodí připlavili se (nebo nedaleko byli od břehu, asi okolo dvou set loket), táhnouce tu sít s rybami."],[9,"jakž vystoupili na břeh, uzřeli řeřavé uhlí a rybu svrchu položenou a chléb."],[10,"Řekl jim Ježíš: Přineste ryb, kterýchž jste nalapali nyní."],[11,"Vstoupil pak Šimon Petr, a vytáhl sít na zem, plnou ryb velikých, sto padesáte a tři. A ačkoli jich tak mnoho bylo, neztrhala se sít."],[12,"Řekl jim Ježíš: Pojďte, obědujte. Žádný pak z učedníků nesměl se ho otázati: Ty kdo jsi? vědouce, že Pán je."],[13,"přišel Ježíš, a vzal ten chléb, a dával jim, i rybu též."],[14,"To již po třetí ukázal se Ježíš učedníkům svým, vstal z mrtvých."]]},{"title":"Ježíš a Petr","range":"Jan 21,15–19","thoughts":[],"verses":[[15,"když poobědvali, řekl Ježíš Šimonovi Petrovi: Šimone Jonášův, miluješ-li mne více než tito? Řekl mu: Ovšem, Pane, ty víš, že tě miluji. Dí mu: Pasiž beránky mé."],[16,"Řekl mu znovu po druhé: Šimone Jonášův, miluješ-li mne? Řekl mu: Ovšem, Pane, ty víš, že tě miluji. Dí mu: Pasiž ovce mé."],[17,"Řekl mu potřetí: Šimone Jonášův, miluješ-li mne? A zarmoutil se Petr, protože mu řekl potřetí: Miluješ-li mne? A odpověděl mu: Pane, ty znáš všechno, ty víš, že tě miluji. Řekl mu Ježíš: Pasiž ovce mé."],[18,"Amen, amen říkám tobě: Když jsi byl mladší, opasovals se, a chodíval jsi, kams chtěl: ale když se sstaráš, ztáhneš ruce své, a jiný tě opáše, a povede, kamž bys ty nechtěl."],[19,"To pak pověděl, znamenaje, kterou by smrtí měl oslaviti Boha. A to pověděv, řekl mu: Poď za mnou."]]},{"title":"Milovaný učedník","range":"Jan 21,20–25","thoughts":[],"verses":[[20,"obrátiv se Petr, uviděl toho učedníka, kteréhož miloval Ježíš, an jde za ním, kterýž i odpočíval za večeří na prsech jeho, a byl řekl: Pane, kdo je ten, kterýž tě zradí?"],[21,"Toho když viděl Petr, dí Ježíšovi: Pane, co pak tento?"],[22,"Řekl mu Ježíš: Chci-li ho nechati, dokudž nepřijdu, co tobě po tom? Ty poď za mnou."],[23,"vyšla řeč ta mezi bratří, že by učedník ten neměl umříti. Ale neřekl byl mu Ježíš, že by neměl umříti, ale: Chci-li ho nechati, dokudž nepřijdu, co tobě po tom?"],[24,"Toť je učedník ten, kterýž svědectví vydává o těchto věcech, a napsal toto, a víme, že pravé je svědectví jeho."],[25,"Jestiť pak i jiných mnoho věcí, kteréž činil Ježíš, kteréž kdyby měly všecky, každá obzvláštně, psány býti, mám za to, že by ten svět nemohl přijíti těch knih, kteréž by napsány byly. Amen."]]}];

